(function(A){Object.assign(A.D,{"G4961":{"l":"συνστρατιώτης","o":2,"ar":"<f>* <o>συν-στρατιώτης</o>، <g>-ου, ὁ</g> </f> <s><b>رفيق في الجندية، زميل جندي</b>. مجازيًا، عن الشركة في الخدمة المسيحية: <r v=\"Phil.2.25\"></r>، <r v=\"Phlm.1.2\"></r>.†</s>","en":"<f>* <o>συν-στρατιώτης</o> (Rec. <g>συσ-</g>), <g>-ου, ὁ</g> </f> <s><b>a fellow-soldier</b> (Plat., Xen., al.). Metaph., of fellowship in Christian service: <r v=\"Phil.2.25\"></r>, <r v=\"Phlm.1.2\"></r> .†</s>"},"G4904":{"l":"συνεργός","o":13,"ar":"<f>** <o>συνεργός</o>، <g>-όν </g></f> <s><b>عامل مع، شريك في العمل</b>: مع المضاف إليه للشخص، <r v=\"Rom.16.3\"></r>، <r v=\"Rom.16.9\"></r>، <r v=\"Rom.16.21\"></r>، <r v=\"Phil.2.25\"></r> <r v=\"Phil.4.3\"></r>، <r v=\"1Thess.3.2\"></r>، <r v=\"Phlm.1.1\"></r>، <r v=\"Phlm.1.24\"></r>؛ <g>θεοῦ</g>، <r v=\"1Cor.3.9\"></r> (جمعًا)، <r v=\"1Thess.3.2\"></r>؛ <g>τ. χαρᾶς ὑηῶν</g>، <r v=\"2Cor.1.24\"></r>؛ <g>τ. ἀληθείᾳ</g>، <r v=\"3John.1.8\"></r>؛ يليه <g>εἰς</g>، <r v=\"2Cor.8.23\"></r>، <r v=\"Col.4.11\"></r>.†</s>","en":"<f>** <o>συνεργός</o>, <g>-όν </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.8.7\"></r> <r v=\"2Macc.14.5\"></r> * ;]</e> </et> <s><b>a fellow-worker</b>: c. gen. pers., <r v=\"Rom.16.3\"></r>, <r v=\"Rom.16.9\"></r>, <r v=\"Rom.16.21\"></r>, <r v=\"Phil.2.25\"></r> <r v=\"Phil.4.3\"></r>, <r v=\"1Thess.3.2\"></r>, Rec., <r v=\"Phlm.1.1\"></r>, <r v=\"Phlm.1.24\"></r>; <g>θεοῦ</g> (cf. Lft., <i>Notes</i>, 41, 188), <r v=\"1Cor.3.9\"></r> (pl.), <r v=\"1Thess.3.2\"></r> [WH] R, mg. (R, txt., <g>διάκονον τοῦ θ.</g>; on the original reading, v. <i>ICC</i>, in l.); <g>τ. χαρᾶς ὑηῶν</g>, <r v=\"2Cor.1.24\"></r>; <g>τ. ἀληθείᾳ</g>, <r v=\"3John.1.8\"></r>; seq. <g>εἰς</g>, <r v=\"2Cor.8.23\"></r>, <r v=\"Col.4.11\"></r>.†</s>"},"G4920":{"l":"συνίημι","o":25,"ar":"<f><o>συν-ίημι</o> و<g>συνίω</g>، </f> <s n=\"1.\"><b>يجمع أو يضع معًا</b>. </s> <s n=\"2.\">مجازيًا، <b>يُدرك، يفهم</b>: <r v=\"Matt.13.13-Matt.13.15\"></r> <i>(السبعينية)</i>، <r v=\"Matt.13.19\"></r> <r v=\"Matt.15.10\"></r>، <r v=\"Mark.4.9\"></r>، <r v=\"Mark.4.12\"></r> <r v=\"Mark.7.14\"></r> <r v=\"Mark.8.17\"></r>، <r v=\"Mark.8.21\"></r> <r v=\"Luke.8.10\"></r>، <r v=\"Acts.7.25\"></r> <r v=\"Acts.28.26-Acts.28.27\"></r>، <r v=\"Rom.15.21\"></r> <i>(السبعينية)</i>، <r v=\"2Cor.10.12\"></r>؛ مع المنصوب للشيء، <r v=\"Matt.13.23\"></r>، <r v=\"Matt.13.51\"></r>، <r v=\"Luke.2.50\"></r> <r v=\"Luke.18.34\"></r> <r v=\"Luke.24.45\"></r>؛ يليه <g>ὅτι</g>، <r v=\"Matt.16.12\"></r> <r v=\"Matt.17.13\"></r>؛ يليه سؤال غير مباشر، <r v=\"Eph.5.17\"></r>؛ <g>ἐπὶ τ. ἄρτοις</g>، <r v=\"Mark.6.52\"></r>؛ بمعنى الاسم، <g>συνίων</g>، <b>إنسان فَهِيم</b>، أي بالمعنى الأخلاقي والديني، <r v=\"Rom.3.11\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>συν-ίημι</o> and <g>συνίω</g> (v. Bl., § 23, 7), </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H995\">בּין</h> hi., <h n=\"H7919\">שׂכל</h> hi. ;] </e> </et> <s n=\"1.\"><b>to bring or set together</b>. </s> <s n=\"2.\">Metaph., <b>to perceive, understand</b>: <r v=\"Matt.13.13-Matt.13.15\"></r> <i>(LXX)</i>, <r v=\"Matt.13.19\"></r> <r v=\"Matt.15.10\"></r>, <r v=\"Mark.4.9\"></r> <i>(WH, mg.)</i>, <r v=\"Mark.4.12\"></r> <r v=\"Mark.7.14\"></r> <r v=\"Mark.8.17\"></r>, <r v=\"Mark.8.21\"></r> <r v=\"Luke.8.10\"></r>, <r v=\"Acts.7.25\"></r> <r v=\"Acts.28.26-Acts.28.27\"></r>, <r v=\"Rom.15.21\"></r> <i>(LXX)</i>, <r v=\"2Cor.10.12\"></r>; c. acc. rei, <r v=\"Matt.13.23\"></r>, <r v=\"Matt.13.51\"></r>, <r v=\"Luke.2.50\"></r> <r v=\"Luke.18.34\"></r> <r v=\"Luke.24.45\"></r>; seq. <g>ὅτι</g>, <r v=\"Matt.16.12\"></r> <r v=\"Matt.17.13\"></r>; seq. quæst. indir., <r v=\"Eph.5.17\"></r>; <g>ἐπὶ τ. ἄρτοις</g>, <r v=\"Mark.6.52\"></r>; as subst., <g>συνίων</g> (<g>ὁ σ.</g>, WH, mg.), <b>a man of understanding</b>, i.e. in moral and religious sense, <r v=\"Rom.3.11\"></r> <i>(LXX)</i>.†</s>"},"G4983":{"l":"σῶμα","o":142,"ar":"<f><o>σῶμα</o>، <g>-τος, τό</g>، </f> <s><b>جسد (جسم)</b>. <s n=\"1.\">بالمعنى الحرفي، عن جسد الإنسان، <s n=\"(a)\">عن الجسد الميت (الجثة): <r v=\"Matt.27.58\"></r>، <r v=\"Matt.27.59\"></r> <r v=\"Mark.15.43\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(b)\">عن الجسد الحي: <r v=\"Luke.11.34\"></r>، <r v=\"1Cor.6.13\"></r>، وفي مواضع أخرى؛ <g>ἐν σ. εἶναι</g>، <r v=\"Heb.13.3\"></r>؛ بوصفه أداة النفس، <g>τὰ διὰ τοῦ σ.</g>، <r v=\"2Cor.5.10\"></r>؛ عكس <g>πνεῦμα</g>، <r v=\"Rom.8.10\"></r>، <r v=\"1Cor.5.3\"></r> <r v=\"1Cor.7.4\"></r>، <r v=\"Jas.2.26\"></r>؛ وعكس <g>ψυχή</g>، <r v=\"Matt.6.25\"></r> <r v=\"Matt.10.28\"></r>، <r v=\"Luke.12.22\"></r> (قارن <r v=\"Wis.1.4\"></r>، وفي مواضع أخرى)؛ وعكس <g>τὸ π. καὶ ἡ ψ.</g>، <r v=\"1Thess.5.23\"></r>؛ <g>σ. ψυχικόν</g>، عكس <g>σ. πνευματικόν</g>، <r v=\"1Cor.15.44\"></r>؛ <g>ὁ ναὸς τοῦ σ. αὐτοῦ</g> (مضاف إليه تفسيري)، <r v=\"John.2.21\"></r>؛ <g>τὸ σ. τ. ταπεινώσεως ἡμῶν</g> (\"مضاف إليه للتعريف\" بأسلوب عبري)، عكس <g>τὸ σ. τ. δοξῆς αὐτοῦ</g>، <r v=\"Phil.3.21\"></r>؛ وكذلك، <g>τὸ σ. τ. σαρκός</g>، <r v=\"Col.1.22\"></r>؛ <g>σ. τοῦ θανάτου</g> (الخاضع للموت)، <r v=\"Rom.7.24\"></r>؛ <g>σ. τ. ἁμαρτίας</g>، <r v=\"Rom.6.6\"></r>؛ </s> <s n=\"(c)\">بأسلوب الكناية (الإطناب)، <g>ἀνθρώπου</g>، ثم مطلقًا <g>σῶμα</g>، <b>شخص (نفس)</b>، وعند الكتّاب المتأخرين، <b>عبد</b>: <r v=\"Rev.18.13\"></r>. </s> </s> <s n=\"2.\">عن أجسام الحيوانات: الحية، <r v=\"Jas.3.3\"></r>؛ والميتة، <r v=\"Heb.13.11\"></r> (<r v=\"Exod.29.14\"></r>، وفي مواضع أخرى). </s> <s n=\"3.\">عن الجمادات (قارن الإنجليزية \"الأجرام السماوية\"): <r v=\"1Cor.15.37\"></r>، <r v=\"1Cor.15.38\"></r>، <r v=\"1Cor.15.40\"></r>. </s> <s n=\"4.\">عن أي مادة جسمية: عكس <g>σκιά</g>، <r v=\"Col.2.17\"></r>. مجازيًا، عن جماعة من الأشخاص يجمعهم رباط مشترك؛ وفي العهد الجديد عن الكنيسة بوصفها جسد المسيح الروحي: <r v=\"Rom.12.5\"></r>، <r v=\"1Cor.10.16\"></r>، <r v=\"1Cor.10.17\"></r> <r v=\"1Cor.12.13\"></r>، <r v=\"1Cor.12.27\"></r>، <r v=\"Eph.1.23\"></r> <r v=\"Eph.2.16\"></r> <r v=\"Eph.4.4\"></r>، <r v=\"Eph.4.12\"></r>، <r v=\"Eph.4.16\"></r> <r v=\"Eph.5.23\"></r>، <r v=\"Eph.5.30\"></r>، <r v=\"Col.1.18\"></r>، <r v=\"Col.1.24\"></r> <r v=\"Col.2.19\"></r> <r v=\"Col.3.15\"></r>؛ <g>ἓν σ. κ. ἓν πνεῦμα</g>، <r v=\"Eph.4.4\"></r>. </s> </s>","en":"<f><o>σῶμα</o>, <g>-τος, τό</g>, </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1472,H1320\">גְּוִיָּה ,בָּשָׂר</h>, etc., and for Aram. <h n=\"????\">נְבֵלָה</h> ;]</e> </et> <s><b>a body</b>. <s n=\"1.\">Prop., of the human body, <s n=\"(a)\">as always in Hom. (opp. to <g>δέμας</g>), of the dead body: <r v=\"Matt.27.58\"></r>, <r v=\"Matt.27.59\"></r> <r v=\"Mark.15.43\"></r>, al.; </s> <s n=\"(b)\">of the living body: <r v=\"Luke.11.34\"></r>, <r v=\"1Cor.6.13\"></r>, al.; <g>ἐν σ. εἶναι</g>, <r v=\"Heb.13.3\"></r>; as the instrument of the soul, <g>τὰ διὰ τοῦ σ.</g>, <r v=\"2Cor.5.10\"></r>; opp. to <g>πνεῦμα</g>, <r v=\"Rom.8.10\"></r>, <r v=\"1Cor.5.3\"></r> <r v=\"1Cor.7.4\"></r>, <r v=\"Jas.2.26\"></r>; to <g>ψυχή</g>, <r v=\"Matt.6.25\"></r> <r v=\"Matt.10.28\"></r>, <r v=\"Luke.12.22\"></r> (cf. <r v=\"Wis.1.4\"></r>, al.); to <g>τὸ π. καὶ ἡ ψ.</g>, <r v=\"1Thess.5.23\"></r>; <g>σ. ψυχικόν</g>, opp. to <g>σ. πνευματικόν</g>, <r v=\"1Cor.15.44\"></r>; <g>ὁ ναὸς τοῦ σ. αὐτοῦ</g> (gen. epexeg.), <r v=\"John.2.21\"></r>; <g>τὸ σ. τ. ταπεινώσεως ἡμῶν</g> (Hebraistic \"gen. of definition\"; M, <i>Pr.</i>, 73 f.; Bl., §35, 5), opp. to <g>τὸ σ. τ. δοξῆς αὐτοῦ</g>, <r v=\"Phil.3.21\"></r>; similarly, <g>τὸ σ. τ. σαρκός</g>, <r v=\"Col.1.22\"></r>; <g>σ. τοῦ θανάτου</g> (subject to death), <r v=\"Rom.7.24\"></r>; <g>σ. τ. ἁμαρτίας</g>, <r v=\"Rom.6.6\"></r>; </s> <s n=\"(c)\">periphr., <g>ἀνθρώπου</g>, then absol., <g>σῶμα</g> (Soph., Xen., al.), <b>a person</b>, and in later writers (Polyb., al.), <b>a slave</b>: <r v=\"Rev.18.13\"></r> (cf. MM, i, ii, xxiv; Deiss., <i>BS</i>, 160). </s> </s> <s n=\"2.\">Of the bodies of animals: living, <r v=\"Jas.3.3\"></r>; dead, <r v=\"Heb.13.11\"></r> ( <r v=\"Exod.29.14\"></r>, al.). </s> <s n=\"3.\">Of inanimate objects (cf. Eng. \"heavenly bodies\"): <r v=\"1Cor.15.37\"></r>, <r v=\"1Cor.15.38\"></r>, <r v=\"1Cor.15.40\"></r> (Diod., al.). </s> <s n=\"4.\">Of any corporeal substance (Plat., al.): opp. to <g>σκιά</g>, <r v=\"Col.2.17\"></r>. Metaph., of a number of persons united by a common bond; in NT, of the Church as the spiritual body of Christ: <r v=\"Rom.12.5\"></r>, <r v=\"1Cor.10.16\"></r>, <r v=\"1Cor.10.17\"></r> <r v=\"1Cor.12.13\"></r>, <r v=\"1Cor.12.27\"></r>, <r v=\"Eph.1.23\"></r> <r v=\"Eph.2.16\"></r> <r v=\"Eph.4.4\"></r>, <r v=\"Eph.4.12\"></r>, <r v=\"Eph.4.16\"></r> <r v=\"Eph.5.23\"></r>, <r v=\"Eph.5.30\"></r>, <r v=\"Col.1.18\"></r>, <r v=\"Col.1.24\"></r> <r v=\"Col.2.19\"></r> <r v=\"Col.3.15\"></r>; <g>ἓν σ. κ. ἓν πνεῦμα</g>, <r v=\"Eph.4.4\"></r>. </s> </s>"},"G4991":{"l":"σωτηρία","o":46,"ar":"<f><o>σωτηρία</o>، <g>-ας, ἡ</g></f> <s><b>نجاة، حفظ، خلاص، سلامة</b>: <r v=\"Acts.7.25\"></r> <r v=\"Acts.27.34\"></r>، <r v=\"Heb.11.7\"></r>؛ <g>ἐξ ἐχθρῶν</g>، <r v=\"Luke.1.71\"></r>. وفي العهد الجديد خاصةً عن الخلاص المسيّاني والروحي (انظر تحت مدخل <g>σώζω</g>): <r v=\"Luke.19.9\"></r>، <r v=\"John.4.22\"></r>، <r v=\"Acts.4.12\"></r> <r v=\"Acts.13.47\"></r>، <r v=\"Rom.11.11\"></r>، <r v=\"2Thess.2.13\"></r>، <r v=\"2Tim.3.15\"></r>، <r v=\"Heb.2.3\"></r> <r v=\"Heb.6.9\"></r>، <r v=\"2Pet.3.15\"></r>، <r v=\"Jude.1.3\"></r>؛ عكس <g>ἀπηώλεια</g>، <r v=\"Phil.1.28\"></r>؛ <g>αἰώνιος-.</g>، <r v=\"Heb.5.9\"></r>؛ <g>ὁ λόγος</g> (<g>τὸ εὐαγγέλιον</g>) <g>τῆς σ.</g>، <r v=\"Acts.13.26\"></r>، <r v=\"Eph.1.13\"></r>؛ <g>ὁδὸς σωτηρίας</g>، <r v=\"Acts.16.17\"></r>؛ <g>κέρας σωτηρίας</g>، <r v=\"Luke.1.69\"></r>؛ <g>ἡμέρα σωτηρίας</g>، <r v=\"2Cor.6.2\"></r> <i>(السبعينية)</i>؛ <g>κατεργάζεσθαι τὴν ἑαυτοῦ σ.</g>، <r v=\"Phil.2.12\"></r>؛ <g>κληρονομεῖν σ.</g>، <r v=\"Heb.1.14\"></r>؛ <g>ὁ ἀρχηγὸς τῆς σ.</g>، <r v=\"Heb.2.10\"></r>؛ <g>εἰς σ.</g>، <r v=\"Rom.1.16\"></r> <r v=\"Rom.10.1\"></r>، <r v=\"Rom.10.10\"></r>، <r v=\"1Pet.2.2\"></r>؛ <g>σ.</g> بوصفه مُلكًا حاضرًا (انظر تحت مدخل <g>σώζω</g>)، <r v=\"Luke.1.77\"></r>، <r v=\"2Cor.1.6\"></r> <r v=\"2Cor.7.10\"></r>، <r v=\"Phil.1.19\"></r>، <r v=\"2Tim.2.10\"></r>؛ وبوصفه سيتحقق على نحو أكمل في المستقبل: <r v=\"Rom.13.11\"></r>، <r v=\"1Thess.5.8-1Thess.5.9\"></r>، <r v=\"Heb.9.28\"></r>، <r v=\"1Pet.1.5\"></r>، <r v=\"1Pet.1.9-1Pet.1.10\"></r>، <r v=\"Rev.7.10\"></r> <r v=\"Rev.12.10\"></r> <r v=\"Rev.19.1\"></r>.†</s>","en":"<f><o>σωτηρία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σωτήρ</g></x>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H3468\">יֶשַׁע</h>, <h n=\"H3444\">יְשׁוּעָה</h>, <h n=\"H8668\">תְּשׁוּעָה</h>, <h n=\"H6413\">פְּלֵיטָה</h>, etc. ;] </e> </et> <s><b>deliverance, preservation, salvation, safety</b> (Lat. <l>salus</l>): <r v=\"Acts.7.25\"></r> <r v=\"Acts.27.34\"></r>, <r v=\"Heb.11.7\"></r>; <g>ἐξ ἐχθρῶν</g>, <r v=\"Luke.1.71\"></r>. In NT esp. of Messianic and spiritual salvation (v.s. <g>σώζω</g>): <r v=\"Luke.19.9\"></r>, <r v=\"John.4.22\"></r>, <r v=\"Acts.4.12\"></r> <r v=\"Acts.13.47\"></r>, <r v=\"Rom.11.11\"></r>, <r v=\"2Thess.2.13\"></r>, <r v=\"2Tim.3.15\"></r>, <r v=\"Heb.2.3\"></r> <r v=\"Heb.6.9\"></r>, <r v=\"2Pet.3.15\"></r>, <r v=\"Jude.1.3\"></r>; opp. to <g>ἀπηώλεια</g>, <r v=\"Phil.1.28\"></r>; <g>αἰώνιος-.</g>, <r v=\"Heb.5.9\"></r>; <g>ὁ λόγος</g> (<g>τὸ εὐαγγέλιον</g>) <g>τῆς σ.</g>, <r v=\"Acts.13.26\"></r>, <r v=\"Eph.1.13\"></r>; <g>ὁδὸς σωτηρίας</g>, <r v=\"Acts.16.17\"></r>; <g>κέρας σωτηρίας</g>, <r v=\"Luke.1.69\"></r>; <g>ἡμέρα σωτηρίας</g>, <r v=\"2Cor.6.2\"></r> <i>(LXX)</i>; <g>κατεργάζεσθαι τὴν ἑαυτοῦ σ.</g>, <r v=\"Phil.2.12\"></r>; <g>κληρονομεῖν σ.</g>, <r v=\"Heb.1.14\"></r>; <g>ὁ ἀρχηγὸς τῆς σ.</g>, <r v=\"Heb.2.10\"></r>; <g>εἰς σ.</g>, <r v=\"Rom.1.16\"></r> <r v=\"Rom.10.1\"></r>, <r v=\"Rom.10.10\"></r>, <r v=\"1Pet.2.2\"></r>; <g>σ.</g> as a present possession (v.s. <g>σώζω</g>), <r v=\"Luke.1.77\"></r>, <r v=\"2Cor.1.6\"></r> <r v=\"2Cor.7.10\"></r>, <r v=\"Phil.1.19\"></r>, <r v=\"2Tim.2.10\"></r>; as more fully realized in the future: <r v=\"Rom.13.11\"></r>, <r v=\"1Thess.5.8-1Thess.5.9\"></r>, <r v=\"Heb.9.28\"></r>, <r v=\"1Pet.1.5\"></r>, <r v=\"1Pet.1.9-1Pet.1.10\"></r>, <r v=\"Rev.7.10\"></r> <r v=\"Rev.12.10\"></r> <r v=\"Rev.19.1\"></r>.†</s>"},"G4982":{"l":"σώζω","o":106,"ar":"<f><o>σώζω</o>، </f> <s><b>يخلِّص</b> من خطر أو أذى أو ألم: <r v=\"Matt.8.25\"></r>، <r v=\"Mark.13.20\"></r>، <r v=\"Luke.23.35\"></r>، وفي مواضع أخرى؛ <g>τ. ψυχήν</g>، <r v=\"Matt.16.25\"></r>، وفي مواضع أخرى؛ يليه <g>ἐκ</g>، <r v=\"John.12.27\"></r>، <r v=\"Heb.5.7\"></r>، <r v=\"Jude.1.5\"></r>؛ عن الشفاء وردّ الصحة: <r v=\"Matt.9.22\"></r>، <r v=\"Mark.5.34\"></r>، وفي مواضع أخرى. وفي العهد الجديد خاصةً عن الخلاص من المرض الروحي والموت، وبهذا المعنى \"يُتكلَّم عنه في الكتاب المقدس إمّا (1) ماضيًا، أو (2) حاضرًا، أو (3) مستقبلاً، بحسب ما إذا كان المنظور إليه الفداء أو النعمة أو المجد. فهكذا (1) <r v=\"Rom.8.24\"></r>، <r v=\"Eph.2.5\"></r>، <r v=\"Eph.2.8\"></r> <r v=\"2Tim.1.9\"></r>، <r v=\"Titus.3.5\"></r>؛ (2) <r v=\"Acts.2.47\"></r>، <r v=\"1Cor.1.18\"></r>، <r v=\"1Cor.15.2\"></r>، <r v=\"2Cor.2.15\"></r>؛ (3) <r v=\"Matt.10.22\"></r>، <r v=\"Rom.13.11\"></r>، <r v=\"Phil.2.12\"></r>، <r v=\"Heb.9.28\"></r>\" (قارن <r v=\"Rom.5.9\"></r>). يليه <g>ἀπό</g>، <r v=\"Matt.1.21\"></r>، <r v=\"Acts.2.40\"></r>، <r v=\"Rom.5.9\"></r>؛ <g>ἐκ</g>، <r v=\"Jas.5.20\"></r>، <r v=\"Jude.1.23\"></r>. </s>","en":"<f><o>σώζω</o> (on the more accurate <g>σῴζω</g>, v. WH, <i>Intr.</i>, § 410; Bl., §3, 1-3), </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3467\">ישׁע</h> hi., also for <h n=\"H4422\">מלט</h> ni., <h n=\"H5337\">נצל</h> ni., etc. ;]</e> </et> <s><b>to save</b> from peril, injury or suffering: <r v=\"Matt.8.25\"></r>, <r v=\"Mark.13.20\"></r>, <r v=\"Luke.23.35\"></r>, al.; <g>τ. ψυχήν</g>, <r v=\"Matt.16.25\"></r>, al.; seq. <g>ἐκ</g>, <r v=\"John.12.27\"></r>, <r v=\"Heb.5.7\"></r>, <r v=\"Jude.1.5\"></r>; of healing, restoring to health: <r v=\"Matt.9.22\"></r>, <r v=\"Mark.5.34\"></r>, al. In NT, esp. of salvation from spiritual disease and death, in which sense it is \"spoken of in Scripture as either (1) past, (2) present, or (3) future, according as redemption, grace, or glory is the point in view. Thus (1) <r v=\"Rom.8.24\"></r>, <r v=\"Eph.2.5\"></r>, <r v=\"Eph.2.8\"></r> <r v=\"2Tim.1.9\"></r>, <r v=\"Titus.3.5\"></r>; (2) <r v=\"Acts.2.47\"></r>, <r v=\"1Cor.1.18\"></r>, <r v=\"1Cor.15.2\"></r>, <r v=\"2Cor.2.15\"></r>; (3) <r v=\"Matt.10.22\"></r>, <r v=\"Rom.13.11\"></r>, <r v=\"Phil.2.12\"></r>, <r v=\"Heb.9.28\"></r>\" (Vau. on <r v=\"Rom.5.9\"></r>). Seq. <g>ἀπό</g>, <r v=\"Matt.1.21\"></r>, <r v=\"Acts.2.40\"></r>, <r v=\"Rom.5.9\"></r>; <g>ἐκ</g>, <r v=\"Jas.5.20\"></r>, <r v=\"Jude.1.23\"></r> (cf. Cremer, 532 ff.). </s>"},"G4972":{"l":"σφραγίζω","o":15,"ar":"<f><o>σφραγίζω </o></f> <s><b>يختم</b>، </s> <s n=\"(a)\">للحفظ والتأمين: <r v=\"Matt.27.66\"></r>، <r v=\"Rev.20.3\"></r>؛ <g>τ. καρπὸν τοῦτον</g>، مجازيًا، <r v=\"Rom.15.28\"></r>؛ </s> <s n=\"(b)\">للإخفاء، ومن ثمَّ مجازيًا، <b>يُخفي (يكتم)</b> (<r v=\"Dan.9.24\"></r>، <r v=\"John.14.17\"></r>): <r v=\"Rev.10.4\"></r> <r v=\"Rev.22.10\"></r>؛ </s> <s n=\"(c)\">للتمييز، <r v=\"Rev.7.3-Rev.7.8\"></r>؛ مجازيًا، <r v=\"Eph.1.13\"></r> <r v=\"Eph.4.30\"></r>؛ الصيغة الوسطى، <r v=\"2Cor.1.22\"></r>؛ </s> <s n=\"(d)\">للتوثيق والمصادقة (<r v=\"Ezra.8.8\"></r>): <r v=\"John.3.33\"></r> <r v=\"John.6.27\"></r> (قارن <g>κατα-σφραγίζω</g>).†</s>","en":"<f><o>σφραγίζω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2856\">חתם</h> (<r v=\"Deut.32.34\"></r>, al.), also for <h n=\"H5640\">סתם</h> (<r v=\"Dan.8.26\"></r>) ;]</e> </et> <s><b>to seal</b>, </s> <s n=\"(a)\">for security: <r v=\"Matt.27.66\"></r>, <r v=\"Rev.20.3\"></r>; <g>τ. καρπὸν τοῦτον</g>, fig. (cf. Deiss., <i>BS</i>, 238 f.; MM, xxiv; <i>DB</i>, iv, 427a), <r v=\"Rom.15.28\"></r>; </s> <s n=\"(b)\">for concealment, hence, metaph., <b>to hide</b> (<r v=\"Dan.9.24\"></r>, <r v=\"John.14.17\"></r>): <r v=\"Rev.10.4\"></r> <r v=\"Rev.22.10\"></r>; </s> <s n=\"(c)\">for distinction, <r v=\"Rev.7.3-Rev.7.8\"></r>; metaph., <r v=\"Eph.1.13\"></r> <r v=\"Eph.4.30\"></r>; mid., <r v=\"2Cor.1.22\"></r>; </s> <s n=\"(d)\">for authentication (<r v=\"Ezra.8.8\"></r>): <r v=\"John.3.33\"></r> <r v=\"John.6.27\"></r> (cf. <g>κατα-σφραγίζω</g>).†</s>"},"G4992":{"l":"σωτήριος","o":5,"ar":"<f><o>σωτήριος</o>، <g>-ον</g></f> <s><b>مخلِّص، جالب للخلاص</b>، وفي العهد الجديد دائمًا بالمعنى الروحي (انظر تحت مدخل <g>σώζω, σωτηρία</g>): <g>ἡ χάρις ἡ σ.</g>، <r v=\"Titus.2.11\"></r>. المحايد، <g>-τὸ σ.</g>، بمعنى الاسم، <b>خلاص</b>: <r v=\"Luke.2.30\"></r>؛ <g>τ. σ. τ. θεοῦ</g>، <r v=\"Luke.3.6\"></r>، <r v=\"Acts.28.28\"></r>؛ <g>περικεφαλαίαν τοῦ σ.</g>، <r v=\"Eph.6.17\"></r>.†</s>","en":"<f><o>σωτήριος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σωτήρ</g></x>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H3444\">יְשׁוּעָה</h>, <h n=\"H8002\">שֶׁלֶם</h>, etc. ;]</e> </et> <s><b>saving, bringing salvation</b>, in NT always in spiritual sense (v.s. <g>σώζω, σωτηρία</g>): <g>ἡ χάρις ἡ σ.</g>, <r v=\"Titus.2.11\"></r>. Neut., <g>-τὸ σ.</g>, as subst. (cl.), <b>salvation</b>: <r v=\"Luke.2.30\"></r>; <g>τ. σ. τ. θεοῦ</g>, <r v=\"Luke.3.6\"></r>, <r v=\"Acts.28.28\"></r>; <g>περικεφαλαίαν τοῦ σ.</g>, <r v=\"Eph.6.17\"></r>.†</s>"},"G4990":{"l":"σωτήρ","o":24,"ar":"<f><o>σωτήρ</o>، <g>-ῆρος, ὁ</g></f> <s><b>مخلِّص، منقذ، حافظ</b>، وهو لقب شائع للملوك في العصرين البطلمي والروماني، وفي العهد الجديد، </s> <s n=\"(a)\">عن الله (كما في السبعينية: <r v=\"Ps.24.5\"></r>، <r v=\"Isa.12.2\"></r>، وفي مواضع أخرى): <r v=\"Luke.1.47\"></r>، <r v=\"1Tim.1.1\"></r> <r v=\"1Tim.2.3\"></r> <r v=\"1Tim.4.10\"></r>، <r v=\"Titus.1.3\"></r> <r v=\"Titus.2.10\"></r> <r v=\"Titus.3.4\"></r>، <r v=\"Jude.1.25\"></r>؛ </s> <s n=\"(b)\">عن المسيح: <r v=\"Luke.2.11\"></r>، <r v=\"Acts.5.31\"></r> <r v=\"Acts.13.23\"></r>، <r v=\"Phil.3.20\"></r>؛ <g>τ. κόσμου</g>، <r v=\"John.4.42\"></r>، <r v=\"1John.4.14\"></r>؛ <g>ἡμῶν</g>، <r v=\"2Tim.1.10\"></r>، <r v=\"Titus.1.4\"></r> <r v=\"Titus.3.6\"></r>؛ <g>θεὸς</g> (<g>κύριος</g>) <g>καὶ σ.</g>، <r v=\"Titus.2.13\"></r>، <r v=\"2Pet.1.1\"></r>، <r v=\"2Pet.1.11\"></r> <r v=\"2Pet.2.20\"></r> <r v=\"2Pet.3.2\"></r>، <r v=\"2Pet.3.18\"></r>؛ <g>σ. τοῦ σώματος</g> (أي الكنيسة؛ انظر تحت مدخل <g>σῶμα</g>، 5)، <r v=\"Eph.5.23\"></r>.†</s>","en":"<f><o>σωτήρ</o>, <g>-ῆρος, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σώζω</g></x>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H3467\">יֵשַׁע</h> and cognate forms ;] </e> </et> <s><b>saviour, deliverer, preserver</b>, a freq. epithet of kings in the Ptolemaic and Rom. periods (Deiss., <i>BS</i>, 83; <i>LAE</i>, 368 f.; MM, xxiv), in NT, </s> <s n=\"(a)\">of God (as LXX: <r v=\"Ps.24.5\"></r>, <r v=\"Isa.12.2\"></r>, al.): <r v=\"Luke.1.47\"></r>, <r v=\"1Tim.1.1\"></r> <r v=\"1Tim.2.3\"></r> <r v=\"1Tim.4.10\"></r>, <r v=\"Titus.1.3\"></r> <r v=\"Titus.2.10\"></r> <r v=\"Titus.3.4\"></r>, <r v=\"Jude.1.25\"></r>; </s> <s n=\"(b)\">of Christ: <r v=\"Luke.2.11\"></r>, <r v=\"Acts.5.31\"></r> <r v=\"Acts.13.23\"></r>, <r v=\"Phil.3.20\"></r>; <g>τ. κόσμου</g>, <r v=\"John.4.42\"></r>, <r v=\"1John.4.14\"></r> (for the general use of the word, v. Westc., in l.); <g>ἡμῶν</g>, <r v=\"2Tim.1.10\"></r>, <r v=\"Titus.1.4\"></r> <r v=\"Titus.3.6\"></r>; <g>θεὸς</g> (<g>κύριος</g>) <g>καὶ σ.</g> (v. Deiss., <i>LAE</i>, 348<i>4</i>; M, <i>Pr.</i>, 84), <r v=\"Titus.2.13\"></r>, <r v=\"2Pet.1.1\"></r>, <r v=\"2Pet.1.11\"></r> <r v=\"2Pet.2.20\"></r> <r v=\"2Pet.3.2\"></r>, <r v=\"2Pet.3.18\"></r>; <g>σ. τοῦ σώματος</g> (i.e. of the Church; v.s. <g>σῶμα</g>, 5), <r v=\"Eph.5.23\"></r>.†</s>"},"G4925":{"l":"συνοικοδομέω","o":1,"ar":"<f>** <o>συν-οικοδομέω</o>، <g>-ῶ </g></f> <s n=\"1.\"><b>يبني معًا أو مع</b> (مع القابل للشخص، <r v=\"1Esd.5.68\"></r>). </s> <s n=\"2.\">عن مواد مختلفة، <b>يبني معًا (يُبنى معًا)</b>: مجازيًا، عن المسيحيين، <r v=\"Eph.2.22\"></r>.†</s>","en":"<f>** <o>συν-οικοδομέω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Esd.5.68\"></r> * ;] </e> </et> <s n=\"1.\"><b>to build together or with</b> (c. dat. pers., <r v=\"1Esd.5.68\"></r>). </s> <s n=\"2.\">Of various materials, <b>to build up together</b> (Thuc., al.): metaph., of Christians, <r v=\"Eph.2.22\"></r>.†</s>"},"G4954":{"l":"σύνσωμος","o":1,"ar":"<f>*† <o>σύν-σωμος</o>، <g>-ον</g> </f> <s><b>من الجسد نفسه (شركاء في الجسد)</b>: <r v=\"Eph.3.6\"></r>.†</s>","en":"<f>*† <o>σύν-σωμος</o> (Rec. <g>συσσ-</g>), <g>-ον</g> </f> <et> <e t=\"derivation\">(&lt; <x><g>σῶμα</g></x>), </e> </et> <s><b>of the same body</b>: <r v=\"Eph.3.6\"></r> (Eccl.).†</s>"},"G4907":{"l":"σύνεσις","o":7,"ar":"<f><o>σύνεσις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>التقاء، تدفُّق معًا</b> . </s> <s n=\"2.\">(أ) <b>فهم</b>: <r v=\"Luke.2.47\"></r>، <r v=\"1Cor.1.19\"></r> <i>(السبعينية)</i>، <r v=\"Eph.3.4\"></r>، <r v=\"Col.1.9\"></r> <r v=\"Col.2.2\"></r>، <r v=\"2Tim.2.7\"></r> </s> <s n=\"(b)\"><b>الفهم، العقل أو الذكاء</b>: <r v=\"Mark.12.33\"></r>.†</s>","en":"<f><o>σύνεσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>συνίημι</g></x>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H999\">בִּינָה</h> and cogn. forms, <h n=\"H4906\">מַשְׂכִּית</h>, <h n=\"H1847\">דַּעַת</h>, <h n=\"H2451\">חׇכְמָה</h>, etc. ;]</e> </et> <s n=\"1.\"><b>a running or flowing together</b> (Hom.). </s> <s n=\"2.\">(a) <b>understanding</b>: <r v=\"Luke.2.47\"></r>, <r v=\"1Cor.1.19\"></r> <i>(LXX)</i>, <r v=\"Eph.3.4\"></r>, <r v=\"Col.1.9\"></r> <r v=\"Col.2.2\"></r>, <r v=\"2Tim.2.7\"></r> </s> <s n=\"(b)\"><b>the understanding, the mind or intelligence</b>: <r v=\"Mark.12.33\"></r>.†</s> <sy><i>SYN.</i>: v.s. <x><g>σοφία</g></x> </sy>"},"G4957":{"l":"συνσταυρόω","o":5,"ar":"<f>* <o>συν-σταυρόω</o>، <g>-ῶ</g>، </f> <s><b>يُصلب مع</b>: المبني للمجهول، مع القابل، <r v=\"John.19.32\"></r>؛ والمعنى نفسه يليه <g>σύν</g>، <r v=\"Matt.27.44\"></r>، <r v=\"Mark.15.32\"></r>. مجازيًا، عن الموت السري للمسيحي مع المسيح: <r v=\"Rom.6.6\"></r>، <r v=\"Gal.2.20\"></r>.†</s>","en":"<f>* <o>συν-σταυρόω</o> (Rec. <g>συσ-</g>), <g>-ῶ</g>, </f> <s><b>to crucify together with</b>: pass., c. dat., <r v=\"John.19.32\"></r>; id. seq. <g>σύν</g>, <r v=\"Matt.27.44\"></r>, <r v=\"Mark.15.32\"></r>. Metaph., of the mystical death of the Christian with Christ: <r v=\"Rom.6.6\"></r>, <r v=\"Gal.2.20\"></r> (Eccl.).†</s>"},"G4997":{"l":"σωφροσύνη","o":3,"ar":"<f>** <o>σωφροσύνη</o>، <g>-ης, ἡ </g></f> <s n=\"(a)\"><b>صحو العقل، رجاحة العقل، رشد</b> (عكس <g>μανία</g>): <r v=\"Acts.26.25\"></r>؛ </s> <s n=\"(b)\"><b>ضبط النفس، تعقُّل، رزانة</b>: <r v=\"1Tim.2.9\"></r>، <r v=\"1Tim.2.15\"></r>.†</s>","en":"<f>** <o>σωφροσύνη</o>, <g>-ης, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ezra.3.13\"></r>, <r v=\"Wis.8.7\"></r>, <r v=\"2Macc.4.37\"></r>, IV Mac <i>6</i> * ;]</e> </et> <s n=\"(a)\"><b>soundness of mind, good sense, sanity</b> (opp. to <g>μανία</g>, Xen.): <r v=\"Acts.26.25\"></r>; </s> <s n=\"(b)\"><b>self-control, sobriety</b>: <r v=\"1Tim.2.9\"></r> (v. Tr., <i>Syn.</i>, § xx), <r v=\"1Tim.2.15\"></r>.†</s>"},"G4960":{"l":"συνστοιχέω","o":1,"ar":"<f>*† <o>συν-στοιχέω</o>، <g>-ῶ</g>، </f> <s><b>يقف في الصف نفسه أو الرتبة نفسها</b>. مجازيًا، <b>يقابل، يناظر</b>: <r v=\"Gal.4.25\"></r>.†</s>","en":"<f>*† <o>συν-στοιχέω</o> (Rec. <g>συσ-</g>), <g>-ῶ</g>, </f> <s><b>to stand in the same rank or line</b> (Polyb). Metaph., <b>to correspond to</b>: <r v=\"Gal.4.25\"></r> (v. Lft., in l.).†</s>"},"G4994":{"l":"σωφρονίζω","o":1,"ar":"<f>** <o>σωφρονίζω </o></f> <s><b>يجعله</b> <g>σώφρων</g>، <b>يردّه إلى رشده، يضبط</b> (الترجمة المنقحة: <i>يدرِّب، ينصح</i>): مع المنصوب للأشخاص، <r v=\"Titus.2.4\"></r>.†</s>","en":"<f>** <o>σωφρονίζω </o></f> <et> <e t=\"septuagint\">[in Aq.: <r v=\"Isa.38.16\"></r> * ;] </e> </et> <s><b>to make</b> <g>σώφρων</g>, <b>recall one to his senses, control</b> (RV, <i>train</i>): c. acc. pers., <r v=\"Titus.2.4\"></r>.†</s>"},"G4942":{"l":"συνυποκρίνομαι","o":1,"ar":"<f>*† <o>συν-υπο-κρίνομαι </o></f> <s><b>يمثّل دورًا مع، يرائي مع</b>: مع القابل، <r v=\"Gal.2.13\"></r>.†</s>","en":"<f>*† <o>συν-υπο-κρίνομαι </o></f> <s><b>to play a part with, dissemble with</b>: c. dat., <r v=\"Gal.2.13\"></r> (Polyb.).†</s>"},"G4941":{"l":"Συντύχη","o":1,"ar":"<f><o>Συντύχη</o>، <g>-τυχή), -ης, ἡ </g></f> <s><b>سنتيخي</b>: <r v=\"Phil.4.2\"></r>.†</s>","en":"<f><o>Συντύχη</o> (T, <g>-τυχή), -ης, ἡ </g></f> <s><b>Syntyche</b>: <r v=\"Phil.4.2\"></r>.†</s>"},"G4937":{"l":"συντρίβω","o":7,"ar":"<f><o>συν-τρίβω </o></f> <s><b>يحطّم، يكسر قطعًا</b>: <r v=\"Matt.12.20\"></r> <i>(السبعينية)</i>، <r v=\"Mark.5.4\"></r>، <r v=\"Mark.14.3\"></r>، <r v=\"John.19.36\"></r> <i>(السبعينية)</i>، <r v=\"Rev.2.27\"></r>؛ عن الأشخاص وأعضاء الجسد: <b>يكسر، يسحق، يرضّ</b>: <r v=\"Luke.9.39\"></r>؛ مجازيًا، <r v=\"Rom.16.20\"></r>.†</s>","en":"<f><o>συν-τρίβω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7665\">שׁבר</h> ;] </e> </et> <s><b>to shatter, break in pieces</b>: <r v=\"Matt.12.20\"></r> <i>(LXX)</i>, <r v=\"Mark.5.4\"></r> <r v=\"Mark.14.3\"></r>, <r v=\"John.19.36\"></r> <i>(LXX)</i>, <r v=\"Rev.2.27\"></r>; of persons and parts of the body, <b>to break, crush, bruise</b>: <r v=\"Luke.9.39\"></r>; fig., <r v=\"Rom.16.20\"></r>.†</s>"},"G4964":{"l":"συνσχηματιζω","o":2,"ar":"<f>* <o>συν-σχηματιζω</o>، </f> <s>في اليونانية الكلاسيكية: <b>يُشكِّل على مثال</b>. المبني للمجهول: <b>يُشاكِل، يتشكّل بشكل</b>: <r v=\"Rom.12.2\"></r>، <r v=\"1Pet.1.14\"></r>.†</s>","en":"<f>* <o>συν-σχηματιζω</o> (Rec. <g>συσ-</g>), </f> <et> <e t=\"derivation\">(&lt; <x><g>σχῆμα</g></x>), </e> </et> <s><b>to conform to</b> (Arist.). Pass., <b>to be conformed to, conform oneself to</b>: <r v=\"Rom.12.2\"></r>, <r v=\"1Pet.1.14\"></r>.†</s>"},"G4988":{"l":"Σωσθένης","o":2,"ar":"<f><o>Σωσθένης</o>، <g>-ου, ὁ </g></f> <s><b>سوستانيس</b>؛ </s> <s n=\"(a)\">رئيس يهودي: <r v=\"Acts.18.7\"></r>؛ </s> <s n=\"(b)\">مسيحي: <r v=\"1Cor.1.1\"></r>.†</s>","en":"<f><o>Σωσθένης</o>, <g>-ου, ὁ </g></f> <s><b>Sosthenes</b>; </s> <s n=\"(a)\">a Jewish ruler: <r v=\"Acts.18.7\"></r>; </s> <s n=\"(b)\">a Christian: <r v=\"1Cor.1.1\"></r>.†</s>"},"G4973":{"l":"σφραγίς","o":16,"ar":"<f><o>σφραγίς</o>، <g>-ῖδος, ἡ </g></f> <s n=\"1.\"><b>ختم، خاتم</b>: <r v=\"Rev.7.2\"></r>. </s> <s n=\"2.\">أثر الختم أو الخاتم: <b>ختم</b> (وعن أغراضه المختلفة انظر تحت مدخل <g>σφραγίζω</g>): على كتاب أو سِفر: <r v=\"Rev.5.1-Rev.5.2\"></r>، <r v=\"Rev.5.5\"></r>، <r v=\"Rev.5.9\"></r>، <r v=\"Rev.6.1\"></r>، <r v=\"Rev.6.3\"></r>، <r v=\"Rev.6.5\"></r>، <r v=\"Rev.6.7\"></r>، <r v=\"Rev.6.9\"></r>، <r v=\"Rev.6.12\"></r>، <r v=\"Rev.8.1\"></r>؛ مجازيًا: <r v=\"Rom.4.11\"></r>، <r v=\"1Cor.9.2\"></r>، <r v=\"2Tim.2.19\"></r>، <r v=\"Rev.9.4\"></r>.†</s>","en":"<f><o>σφραγίς</o>, <g>-ῖδος, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.28.11\"></r>, al. (<h n=\"H2368\">חֹתָם</h>) <r v=\"Exod.35.22\"></r> (<h n=\"H2397\">חָח</h>), <r v=\"Sir.17.22\"></r>, al. ;] </e> </et> <s n=\"1.\"><b>a seal, signet</b>: <r v=\"Rev.7.2\"></r>. </s> <s n=\"2.\">The impression of a seal or signet, <b>a seal</b> (on its various purposes, v.s. <g>σφραγίζω</g>): on a book or roll, <r v=\"Rev.5.1-Rev.5.2\"></r>, <r v=\"Rev.5.5\"></r>, <r v=\"Rev.5.9\"></r> <r v=\"Rev.6.1\"></r>, <r v=\"Rev.6.3\"></r>, <r v=\"Rev.6.5\"></r>, <r v=\"Rev.6.7\"></r>, <r v=\"Rev.6.9\"></r>, <r v=\"Rev.6.12\"></r> <r v=\"Rev.8.1\"></r>; metaph., <r v=\"Rom.4.11\"></r>, <r v=\"1Cor.9.2\"></r>, <r v=\"2Tim.2.19\"></r>, <r v=\"Rev.9.4\"></r>.†</s>"},"G4984":{"l":"σωματικός","o":3,"ar":"<f>** <o>σωματικός</o>، <g>-ή, -όν</g></f> <s n=\"(a)\"><b>خاص بالجسد أو للجسد، جسدي</b>: <g>γυμνασία</g>: <r v=\"1Tim.4.8\"></r>؛ </s> <s n=\"(b)\">(عكس <g>ἀσώματος</g>) <b>جسمي، مادي (ذو جسم)</b>: <g>εἶδος</g>: <r v=\"Luke.3.22\"></r>.†</s>","en":"<f>** <o>σωματικός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σῶμα</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"4Macc.1.32\"></r> <r v=\"4Macc.3.1\"></r> * ;] </e> </et> <s n=\"(a)\"><b>of or for the body, bodily</b>: <g>γυμνασία</g>, <r v=\"1Tim.4.8\"></r>; </s> <s n=\"(b)\">(opp. to <g>ἀσώματος</g>) <b>bodily, corporeal</b>: <g>εἶδος</g>, <r v=\"Luke.3.22\"></r>.†</s>"},"G4958":{"l":"συνστέλλω","o":2,"ar":"<f><o>συν-στέλλω</o></f> <s n=\"1.\"><b>ضمّ، قلّص، قصّر</b>: عن الزمان: <r v=\"1Cor.7.29\"></r>. </s> <s n=\"2.\"><b>لفّ</b>: عن تكفين جسد للدفن، مع المنصوب: <r v=\"Acts.5.6\"></r>.†</s>","en":"<f><o>συν-στέλλω</o></f> <et> <e t=\"derivation\">(Rec. <g>συσ-</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Judg.8.28\"></r> <r v=\"Judg.11.33\"></r> (<h n=\"H3665\">כּנע</h> ni.), <r v=\"Sir.4.31\"></r>, al. ;]</e> </et> <s n=\"1.\"><b>to draw together, contract, shorten</b>: of time, <r v=\"1Cor.7.29\"></r>. </s> <s n=\"2.\"><b>to wrap up</b>: of enshrouding a body for burial (Eur.), c. acc., <r v=\"Acts.5.6\"></r>.†</s>"},"G4914":{"l":"συνήθεια","o":3,"ar":"<f>** <o>συνήθεια</o>، <g>-ας, ἡ</g></f> <s n=\"1\"><b>ألفة، مخالطة</b>. </s> <s n=\"2.\"><b>عادة، عُرف</b>: <r v=\"John.18.39\"></r>، <r v=\"1Cor.11.16\"></r>؛ مع المضاف إليه المفعول: <b>الاعتياد على، قوة العادة</b> تجاه، <r v=\"1Cor.8.7\"></r>.†</s>","en":"<f>** <o>συνήθεια</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἦθος</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"4Macc.2.12\"></r> <r v=\"4Macc.6.13\"></r> <r v=\"4Macc.13.22\"></r>, <r v=\"4Macc.13.27\"></r> * ;] </e> </et> <s n=\"1\"><b>intimacy</b>. </s> <s n=\"2.\"><b>habit, custom</b>: <r v=\"John.18.39\"></r>, <r v=\"1Cor.11.16\"></r>; c. gen. obj. (cf. Æschin., 23, 37, and v. MM, xxiv), <b>habitual use, force of habit</b> with respect to, <r v=\"1Cor.8.7\"></r>.†</s>"},"G4906":{"l":"συνεσθίω","o":5,"ar":"<f><o>συν-εσθίω </o></f> <s><b>أكل مع</b> أحد: مع قابل الشخص، <r v=\"Luke.15.2\"></r>، <r v=\"Acts.10.41\"></r>، <r v=\"Acts.11.3\"></r>، <r v=\"1Cor.5.11\"></r>؛ يليه <g>μετά</g> مع مضاف إليه الشخص، <r v=\"Gal.2.12\"></r>.†</s>","en":"<f><o>συν-εσθίω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Gen.43.32\"></r>, <r v=\"Exod.18.12\"></r> (<h n=\"H398\">אכל</h>), <r v=\"2Kgs.12.17\"></r> (<h n=\"H1262\">בּרה</h>), <r v=\"Ps.101.5\"></r> * ;] </e> </et> <s><b>to eat with</b> one: c. dat. pers., <r v=\"Luke.15.2\"></r>, <r v=\"Acts.10.41\"></r> <r v=\"Acts.11.3\"></r>, <r v=\"1Cor.5.11\"></r>; seq. <g>μετά</g>, c. gen. pers., <r v=\"Gal.2.12\"></r>.†</s>"},"G4996":{"l":"σωφρόνως","o":1,"ar":"<f>** <o>σωφρόνως </o></f> ظرف، <s><b>بتعقّل، بحكمة، بتعفّف</b>: <r v=\"Titus.2.12\"></r>.†</s>","en":"<f>** <o>σωφρόνως </o></f> adv., <et> <e t=\"septuagint\">[in LXX: <r v=\"Wis.9.11\"></r> * ;]</e> </et> <s><b>with sound mind, prudently, soberly</b>: <r v=\"Titus.2.12\"></r>.†</s>"},"G4903":{"l":"συνεργέω","o":5,"ar":"<f>** <o>συνεργέω</o>، <g>-ῶ </g></f> <s n=\"1.\">أصلاً: <b>عمل مع، عمل معًا</b>: مطلقًا، <r v=\"Mark.16.20\"></r>، <r v=\"1Cor.16.16\"></r>، <r v=\"2Cor.6.1\"></r>؛ مع القابل، <r v=\"Jas.2.22\"></r>؛ قابل المنفعة، <r v=\"Rom.8.28\"></r> (لكن انظر أدناه). </s> <s n=\"2.\">عند الكتّاب اليونانيين المتأخرين، متعدٍّ: <b>جعل الأشياء تعمل معًا</b>: مع المنصوب للشيء، <r v=\"Rom.8.28\"></r> (لكن انظر أعلاه).†</s>","en":"<f>** <o>συνεργέω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Esd.7.2\"></r>, <r v=\"1Macc.12.1\"></r> * ;] </e> </et> <s n=\"1.\">prop., <b>to work together (with)</b>: absol., <r v=\"Mark.16.20\"></r>, <r v=\"1Cor.16.16\"></r>, <r v=\"2Cor.6.1\"></r>; c. dat., <r v=\"Jas.2.22\"></r>; dat. commod., <r v=\"Rom.8.28\"></r>, T, R, txt. (but v. infr.). </s> <s n=\"2.\">In Hellenistic writers (M, <i>Pr.</i>, 65), trans., <b>to cause to work together</b> (cf. <i>ICC</i>, in l.): c. acc. rei, <r v=\"Rom.8.28\"></r> [WH] R, mg. (but v. supr.).†</s>"},"G4959":{"l":"συνστενάζω","o":1,"ar":"<f>* <o>συν-στενάζω</o>، </f> <s><b>أنّ معًا أو أنّ مع</b>: <r v=\"Rom.8.22\"></r>.†</s>","en":"<f>* <o>συν-στενάζω</o> (Rec. <g>συσ-</g>), </f> <s><b>to groan together or with</b>: <r v=\"Rom.8.22\"></r> (c. dat. pers., Eur., Ion., 935).†</s>"},"G4905":{"l":"συνέρχομαι","o":30,"ar":"<f><o>συν-έρχομαι </o></f> <s n=\"1.\"><b>اجتمع، احتشد</b>: <r v=\"Mark.3.20\"></r> <r v=\"Mark.14.53\"></r>، <r v=\"Acts.1.6\"></r> <r v=\"Acts.2.6\"></r> <r v=\"Acts.10.27\"></r> <r v=\"Acts.16.13\"></r> <r v=\"Acts.19.32\"></r> <r v=\"Acts.21.22\"></r> <r v=\"Acts.22.30\"></r> <r v=\"Acts.28.17\"></r>، <r v=\"1Cor.14.26\"></r>؛ يليه <g>εἰς</g>، مع المنصوب للمكان، <r v=\"Acts.5.16\"></r>؛ <g>ἐπὶ τ. αὐτό</g>، <r v=\"1Cor.11.20\"></r> <r v=\"1Cor.14.23\"></r>؛ مع القابل للشخص، <r v=\"Mark.14.53\"></r>، <r v=\"John.11.33\"></r>؛ <g>ἐν ἐκκλησίᾳ</g>، <r v=\"1Cor.11.18\"></r>؛ <g>ἐνθάδε</g>، <r v=\"Acts.25.17\"></r>؛ <g>αὐτοῦ</g>، <r v=\"Mark.6.33\"></r>؛ <g>ὅπου</g>، <r v=\"John.18.20\"></r>؛ مع المصدر، <r v=\"Luke.5.15\"></r>؛ <g>εἰς τ. φαγεῖν</g>، <r v=\"1Cor.11.33\"></r>؛ <g>εἰς τ. ἧσσον</g>، <r v=\"1Cor.11.17\"></r>، <r v=\"1Cor.11.34\"></r>؛ عن العلاقة الزوجية (<g>γυναικί</g> أو مطلقًا)، <r v=\"Matt.1.18\"></r>. </s> <s n=\"2.\">بمعنى متأخر: <b>رافق</b>: مع القابل للشخص، <r v=\"Luke.23.55\"></r>، <r v=\"Acts.1.21\"></r> <r v=\"Acts.9.39\"></r> <r v=\"Acts.10.23\"></r>، <r v=\"Acts.10.45\"></r> <r v=\"Acts.11.12\"></r>؛ يليه <g>σύν</g>، <r v=\"Acts.21.16\"></r>؛ <g>εἰς</g>، <r v=\"Acts.15.38\"></r>.†</s>","en":"<f><o>συν-έρχομαι </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1980\">הלךְ</h>, <h n=\"H935\">בּוֹא</h>, <h n=\"H622\">אסף</h> ni., etc. ;] </e> </et> <s n=\"1.\">(cl.) <b>to come together, assemble</b>: <r v=\"Mark.3.20\"></r> <r v=\"Mark.14.53\"></r>, T, WH, txt., <r v=\"Acts.1.6\"></r> <r v=\"Acts.2.6\"></r> <r v=\"Acts.10.27\"></r> <r v=\"Acts.16.13\"></r> <r v=\"Acts.19.32\"></r> <r v=\"Acts.21.22\"></r> <r v=\"Acts.22.30\"></r> <r v=\"Acts.28.17\"></r>, <r v=\"1Cor.14.26\"></r>; seq. <g>εἰς</g>, c. acc loc., <r v=\"Acts.5.16\"></r>; <g>ἐπὶ τ. αὐτό</g>, <r v=\"1Cor.11.20\"></r> <r v=\"1Cor.14.23\"></r>; c. dat. pers., <r v=\"Mark.14.53\"></r>, WH, mg., R (<g>πρὸς αὐτόν</g>, v. Field, <i>Notes</i>, 40), <r v=\"John.11.33\"></r>; <g>ἐν ἐκκλησίᾳ</g>, <r v=\"1Cor.11.18\"></r>; <g>ἐνθάδε</g>, <r v=\"Acts.25.17\"></r>; <g>αὐτοῦ</g>, <r v=\"Mark.6.33\"></r>, WH, mg. (cf. WH, <i>Intr.</i>, 95 ff.); <g>ὅπου</g>, <r v=\"John.18.20\"></r>; c. inf., <r v=\"Luke.5.15\"></r>; <g>εἰς τ. φαγεῖν</g>, <r v=\"1Cor.11.33\"></r>; <g>εἰς τ. ἧσσον</g>, <r v=\"1Cor.11.17\"></r>, <r v=\"1Cor.11.34\"></r>; of sexual intercourse (Xen., al.; <g>γυναικί</g> or absol.), <r v=\"Matt.1.18\"></r>. </s> <s n=\"2.\">In later sense (v. exx. in Milligan, <i>Selections</i>, 64, 105), <b>to accompany</b>: c. dat. pers., <r v=\"Luke.23.55\"></r>, <r v=\"Acts.1.21\"></r> <r v=\"Acts.9.39\"></r> <r v=\"Acts.10.23\"></r>, <r v=\"Acts.10.45\"></r> <r v=\"Acts.11.12\"></r>; seq. <g>σύν</g>, <r v=\"Acts.21.16\"></r>; <g>εἰς</g>, <r v=\"Acts.15.38\"></r>.†</s>"},"G4921":{"l":"συνίστημι","o":null,"ar":"<f><o>συν-ίστημι</o> </f> <s n=\"1.\">متعدٍّ، </s> <s n=\"(a)\"><b>زكّى، مدح، أوصى بـ</b>: مع المنصوب للشخص، <r v=\"2Cor.3.1\"></r> <r v=\"2Cor.6.4\"></r> <r v=\"2Cor.10.12\"></r>، <r v=\"2Cor.10.18\"></r>؛ ونفسه مع القابل، <r v=\"Rom.16.1\"></r> (كما يرد كثيرًا في مطلع الرسائل)، <r v=\"2Cor.5.12\"></r>؛ يليه <g>πρός</g>، <r v=\"2Cor.4.2\"></r>؛ المبني للمجهول، يليه <g>ὑπό</g>، <r v=\"2Cor.12.11\"></r>؛ </s> <s n=\"(b)\"><b>أظهر، برهن، أثبت</b>: مع المنصوب، <r v=\"Rom.3.5\"></r> <r v=\"Rom.5.8\"></r>، <r v=\"2Cor.6.4\"></r>؛ مع منصوبين، <r v=\"Gal.2.13\"></r>؛ مع المنصوب والمصدر، <r v=\"2Cor.7.11\"></r> </s> <s n=\"2.\">لازم، التام، <g>συνέστηκα</g> (وكذلك الماضي البسيط الثاني والماضي الأتم)؛ </s> <s n=\"(a)\"><b>وقف مع أو بالقرب من</b>: <r v=\"Luke.9.32\"></r>؛ </s> <s n=\"(b)\"><b>تألّف من، قام، تماسك (قام به الكل)</b>: <r v=\"Col.1.17\"></r>، <r v=\"2Pet.3.5\"></r>.†</s>","en":"<f><o>συν-ίστημι</o> </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6680\">צוה</h> pi., <h n=\"H6950\">קהל</h> ni., etc.; <r v=\"1Macc.12.43\"></r>, <r v=\"2Macc.4.24\"></r>, <r v=\"3Macc.1.19\"></r> (and freq. in these books) ;]</e> </et> <s n=\"1.\">trans., </s> <s n=\"(a)\"><b>to commend, recommend</b>: c. acc. pers., <r v=\"2Cor.3.1\"></r> <r v=\"2Cor.6.4\"></r> <r v=\"2Cor.10.12\"></r>, <r v=\"2Cor.10.18\"></r>; id. c. dat., <r v=\"Rom.16.1\"></r> (as freq. at the beginning of a letter; Deiss., <i>LAE</i>, 226), <r v=\"2Cor.5.12\"></r>; seq. <g>πρός</g>, <r v=\"2Cor.4.2\"></r>; pass., seq. <g>ὑπό</g>, <r v=\"2Cor.12.11\"></r>; </s> <s n=\"(b)\"><b>to show, prove, establish</b>: c. acc., <r v=\"Rom.3.5\"></r> <r v=\"Rom.5.8\"></r>, <r v=\"2Cor.6.4\"></r>; dupl. acc., <r v=\"Gal.2.13\"></r>; acc. et inf., <r v=\"2Cor.7.11\"></r> </s> <s n=\"2.\">Intrans., pf., <g>συνέστηκα</g> (as also 2 aor. and plpf.); </s> <s n=\"(a)\"><b>to stand with or near</b>: <r v=\"Luke.9.32\"></r>; </s> <s n=\"(b)\"><b>to be composed of, consist, cohere</b>: <r v=\"Col.1.17\"></r> (v. Lft., in l.), <r v=\"2Pet.3.5\"></r>.†</s>"},"G4915":{"l":"συνηλικιώτης","o":1,"ar":"<f>*† <o>συν-ηλικιώτης</o></f> <s><b>تِرْب، من السنّ نفسها</b>: <r v=\"Gal.1.14\"></r>.†</s>","en":"<f>*† <o>συν-ηλικιώτης</o></f> <et> <e t=\"derivation\">(&lt; <x><g>ἡλικία</g></x>), = <g>συνῆλιζ</g> (Æsch.), </e> </et> <s><b>one of the same age, an equal in age</b>: <r v=\"Gal.1.14\"></r>.†</s>"},"G4978":{"l":"σχίσμα","o":8,"ar":"<f>* <o>σχίσμα</o>، <g>-τος, τό</g></f> <s><b>خَرْق، شَقّ</b>: <r v=\"Matt.9.16\"></r>، <r v=\"Mark.2.21\"></r>. مجازيًا: <b>شقاق، انشقاق</b>: <r v=\"John.7.43\"></r> <r v=\"John.9.16\"></r> <r v=\"John.10.19\"></r>، <r v=\"1Cor.1.10\"></r> <r v=\"1Cor.11.18\"></r> <r v=\"1Cor.12.25\"></r>.†</s>","en":"<f>* <o>σχίσμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σχίζω</g></x>), </e> </et> <s><b>a rent</b> (Arist., al.): <r v=\"Matt.9.16\"></r>, <r v=\"Mark.2.21\"></r>. Metaph., <b>a dissension, division</b>: <r v=\"John.7.43\"></r> <r v=\"John.9.16\"></r> <r v=\"John.10.19\"></r>, <r v=\"1Cor.1.10\"></r> <r v=\"1Cor.11.18\"></r> <r v=\"1Cor.12.25\"></r>.†</s> <sy><i>SYN.</i>: v.s. <x><g>αἵρεσις</g></x> </sy>"},"G4947":{"l":"Συρία","o":8,"ar":"<f><o>Συρία</o>، <g>-ας, ή </g></f> <s><b>سورية</b>: <r v=\"Matt.4.24\"></r>، <r v=\"Luke.2.2\"></r>، <r v=\"Acts.15.23\"></r>، <r v=\"Acts.15.41\"></r> <r v=\"Acts.18.18\"></r> <r v=\"Acts.20.3\"></r> <r v=\"Acts.21.3\"></r>، <r v=\"Gal.1.21\"></r>.†</s>","en":"<f><o>Συρία</o>, <g>-ας, ή </g></f> <s><b>Syria</b>: <r v=\"Matt.4.24\"></r>, <r v=\"Luke.2.2\"></r>, <r v=\"Acts.15.23\"></r>, <r v=\"Acts.15.41\"></r> <r v=\"Acts.18.18\"></r> <r v=\"Acts.20.3\"></r> <r v=\"Acts.21.3\"></r>, <r v=\"Gal.1.21\"></r>.†</s>"},"G4912":{"l":"συνέχω","o":12,"ar":"<f><o>συν-έχω </o></f> <s n=\"1.\"><b>يضمّ معًا</b> (<g>τ. συνέχον τ. πάντα</g>، <r v=\"Wis.1.7\"></r>): عن سدّ الآذان، <r v=\"Acts.7.57\"></r> (<g>τ. στόμα</g>، <r v=\"Isa.52.15\"></r>)؛ <b>يحاصر، يضيّق عليه من كل جانب</b>: <r v=\"Luke.8.45\"></r>، <r v=\"Luke.19.43\"></r>. </s> <s n=\"2.\"><b>يمسك بقوة</b>؛ </s> <s n=\"(a)\">عن السجين: <b>يحتجز، يحرس</b>: <r v=\"Luke.22.63\"></r>؛ </s> <s n=\"(b)\"><b>يحصر، يضطرّ</b>: <r v=\"2Cor.5.14\"></r>؛ في المبني للمجهول، <r v=\"Luke.12.50\"></r>، <r v=\"Acts.18.5\"></r> (<g>τ. λόγῳ</g>)، <r v=\"Phil.1.23\"></r>؛ وفي المبني للمجهول عن العلل: <b>يُصاب أو يُبتلى بـ، يعاني من</b>: <r v=\"Matt.4.24\"></r>، <r v=\"Luke.4.38\"></r>، <r v=\"Luke.8.37\"></r>، <r v=\"Acts.28.8\"></r>.†</s>","en":"<f><o>συν-έχω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6113\">עצר</h>, <h n=\"H2266\">חבר</h>, etc. ;]</e> </et> <s n=\"1.\"><b>to hold together</b> (<g>τ. συνέχον τ. πάντα</g>, <r v=\"Wis.1.7\"></r>): of closing the ears, <r v=\"Acts.7.57\"></r> (<g>τ. στόμα</g>, <r v=\"Isa.52.15\"></r>); <b>to hem in, press on every side</b>: <r v=\"Luke.8.45\"></r> <r v=\"Luke.19.43\"></r>. </s> <s n=\"2.\"><b>to hold fast</b>; </s> <s n=\"(a)\">of a prisoner, <b>to hold in charge</b> (Luc.; cf. exx. in Deiss., <i>BS</i>, 160; MM, xxiv): <r v=\"Luke.22.63\"></r>; </s> <s n=\"(b)\"><b>to constrain</b>: <r v=\"2Cor.5.14\"></r>; pass., <r v=\"Luke.12.50\"></r>, <r v=\"Acts.18.5\"></r> (<g>τ. λόγῳ</g>; cf. Field, <i>Notes</i>, 128), <r v=\"Phil.1.23\"></r>; in pass., of ills, <b>to be seized or afflicted by, suffering from</b>: <r v=\"Matt.4.24\"></r>, <r v=\"Luke.4.38\"></r> <r v=\"Luke.8.37\"></r>, <r v=\"Acts.28.8\"></r>.†</s>"},"G4989":{"l":"Σωσίπατρος","o":1,"ar":"<f><o>Σωσίπατρος</o>، <g>-ου, ὁ </g></f> <s><b>سوسيباترس</b>: <r v=\"Rom.16.21\"></r>.†</s>","en":"<f><o>Σωσίπατρος</o>, <g>-ου, ὁ </g></f> <s><b>Sosipater</b>: <r v=\"Rom.16.21\"></r>.†</s>"},"G4928":{"l":"συνοχή","o":2,"ar":"<f><o>συν-οχή</o>، <g>-ῆς, ή</g></f> <s n=\"1.\"><b>ضمّ أو انضمام معًا</b>. </s> <s n=\"2.\"><b>مضيق، مكان ضيّق</b>. مجازيًا: <b>ضيق، كرب</b>: <r v=\"Luke.21.25\"></r>؛ <g>καρδίας</g>، <r v=\"2Cor.2.4\"></r>.†</s>","en":"<f><o>συν-οχή</o>, <g>-ῆς, ή</g></f> <et> <e t=\"derivation\">(&lt; <x><g>συνέχω</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Judg.2.3\"></r> (?), <r v=\"Job.30.3\"></r> (<h n=\"H7722\">שׁוֺאָה</h>), <r v=\"Job.38.28\"></r> A; <r v=\"Mic.5.1\"></r> (4:14), <r v=\"Jer.52.5\"></r> (<h n=\"H4692\">מָצוֹר</h>) * ;]</e> </et> <s n=\"1.\"><b>a holding or being held together</b>. </s> <s n=\"2.\"><b>a narrow place</b> (Hom., al.). Metaph., <b>straits, distress</b>: <r v=\"Luke.21.25\"></r>; <g>καρδίας</g>, <r v=\"2Cor.2.4\"></r>.†</s>"},"G4908":{"l":"συνετός","o":4,"ar":"<f><o>συνετός</o>، <g>ή, -όν</g></f> <s><b>فهيم، حكيم، ذو فطنة</b>: <r v=\"Matt.11.25\"></r>، <r v=\"Luke.10.21\"></r>، <r v=\"Acts.13.7\"></r>، <r v=\"1Cor.1.19\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>συνετός</o>, <g>ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <x><g>συνίημι</g></x>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H995\">נָבוֺן</h>, <h n=\"H2450\">חָכָם</h>, etc. ;]</e> </et> <s><b>intelligent, sagacious, understanding</b>: <r v=\"Matt.11.25\"></r>, <r v=\"Luke.10.21\"></r>, <r v=\"Acts.13.7\"></r>, <r v=\"1Cor.1.19\"></r> <i>(LXX)</i>.†</s>"},"G4985":{"l":"σωματικῶς","o":1,"ar":"<f>* <o>σωματικῶς </o></f> ظرف، <s><b>جسديًّا، بالجسد</b>: <r v=\"Col.2.9\"></r>.†</s>","en":"<f>* <o>σωματικῶς </o></f> adv., <s><b>bodily, corporeally</b>: <r v=\"Col.2.9\"></r> (v. <i>ICC</i>, Lft., in l.).†</s>"},"G4916":{"l":"συνθάπτω","o":2,"ar":"<f>* <o>συν-θάπτω </o></f> <s><b>يُدفن مع</b>: بالمعنى الرمزي، عن المعمودية، <g>αὐτῷ</g> (<b>مع المسيح</b>)، <r v=\"Rom.6.4\"></r>، <r v=\"Col.2.12\"></r>.†</s>","en":"<f>* <o>συν-θάπτω </o></f> <s><b>to bury together with</b>: in symbolical sense, of baptism, <g>αὐτῷ</g> (<b>with Christ</b>), <r v=\"Rom.6.4\"></r>, <r v=\"Col.2.12\"></r>.†</s>"},"G4993":{"l":"σωφρονέω","o":6,"ar":"<f>* <o>σωφρονέω</o>، <g>-ῶ</g></f> <s n=\"(a)\"><b>كان صحيح العقل، كان عاقلاً (في وعيه)</b>: <r v=\"Mark.5.15\"></r>، <r v=\"Luke.8.35\"></r>؛ عكس <g>ἐκστῆναι</g>، <r v=\"2Cor.5.13\"></r>؛ </s> <s n=\"(b)\"><b>تعقّل، كان رزينًا، ضبط نفسه</b> (عكس <g>μαίνεσθαι, ὑβρίζειν</g> ونحوها): <r v=\"Titus.2.6\"></r>؛ عكس <g>ὑπερφρονεῖν</g>، <r v=\"Rom.12.3\"></r>؛ <g>σ. καὶ νήφειν</g>، <r v=\"1Pet.4.7\"></r>.†</s>","en":"<f>* <o>σωφρονέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σώφρων</g></x>), </e> </et> <s n=\"(a)\"><b>to be of sound mind or in one's right mind</b>: <r v=\"Mark.5.15\"></r>, <r v=\"Luke.8.35\"></r>; opp. to <g>ἐκστῆναι</g>, <r v=\"2Cor.5.13\"></r> (Hdt.); </s> <s n=\"(b)\"><b>to be temperate, discreet, self-controlled</b> (opp. to <g>μαίνεσθαι, ὑβρίζειν</g>, etc.; Æsch., Thuc., al.): <r v=\"Titus.2.6\"></r>; opp. to <g>ὑπερφρονεῖν</g>, <r v=\"Rom.12.3\"></r>; <g>σ. καὶ νήφειν</g>, <r v=\"1Pet.4.7\"></r>.†</s>"},"G4932":{"l":"συντέμνω","o":1,"ar":"<f><o>συν-τέμνω </o></f> <s n=\"1.\"><b>قطّع</b>. </s> <s n=\"2.\"><b>قطع، قصّر، اختصر</b>: مجازيًا، <g>λόγον</g>، <r v=\"Rom.9.28\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>συν-τέμνω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2782\">חרץ</h> ;] </e> </et> <s n=\"1.\"><b>to cut in pieces</b>. </s> <s n=\"2.\"><b>to cut down, cut short</b>: metaph., <g>λόγον</g>, <r v=\"Rom.9.28\"></r> <i>(LXX)</i> (Hdt., Plat., Eur., al.).†</s>"},"G4987":{"l":"σωρεύω","o":2,"ar":"<f><o>σωρεύω </o> </f> <s n=\"(a)\"><b>كوّم على</b>: مع المنصوب يليه <g>ἐπί</g> مع المنصوب، <r v=\"Rom.12.20\"></r> <i>(السبعينية)</i>؛ </s> <s n=\"(b)\"><b>حمّل بـ</b>: مع المنصوب والقابل، مجازيًا، <g>ἁμαρτίαις</g>، <r v=\"2Tim.3.6\"></r> (<i>مثقَّلات بـ</i>).†</s>","en":"<f><o>σωρεύω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Prov.25.22\"></r> (<h n=\"H2846\">חתה</h>), <r v=\"Jdt.15.11\"></r> * ;] </e> </et> <s n=\"(a)\"><b>to heap on</b>: c. acc. seq. <g>ἐπί</g> c. acc., <r v=\"Rom.12.20\"></r> <i>(LXX)</i> (Arist., al.); </s> <s n=\"(b)\"><b>to heap with</b>: c. acc. et dat., metaph., <g>ἁμαρτίαις</g>, <r v=\"2Tim.3.6\"></r> (<i>overwhelmed with</i>, Field, <i>Notes</i>, 217) (Polyb.).†</s>"},"G4943":{"l":"συνυπουργέω","o":1,"ar":"<f>* <o>συν-υπουργέω</o>، <g>-ῶ </g> </f> <s><b>ساعد مع غيره، اشترك في الخدمة</b>: مع القابل للأداة، <r v=\"2Cor.1.11\"></r>.†</s>","en":"<f>* <o>συν-υπουργέω</o>, <g>-ῶ </g></f> <s><b>to help together, join in serving</b>: c. dat. instr., <r v=\"2Cor.1.11\"></r>.†</s>"},"G4980":{"l":"σχολάζω","o":2,"ar":"<f><o>σχολάζω</o></f> <s><b>كان في فراغ</b>، ومن ثمّ: كان له وقت أو فرصة لـ، <b>تفرّغ لـ، انصرف إلى</b>: <r v=\"1Cor.7.5\"></r>؛ وعن الأشياء: <b>كان شاغرًا، فارغًا</b>: <g>οἶκος</g>، <r v=\"Matt.12.44\"></r>، <r v=\"Luke.11.25\"></r>.†</s>","en":"<f><o>σχολάζω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>σχολή</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Exod.5.8\"></r>, <r v=\"Exod.5.17\"></r>, <r v=\"Ps.46.10\"></r> (<h n=\"H7503\">רפה</h> ni., hi.) * ;] </e> </et> <s><b>to be at leisure</b>, hence, to have time or opportunity for, <b>to devote oneself to, be occupied in</b>: <r v=\"1Cor.7.5\"></r>; of things, to be <b>unoccupied, empty</b> (Plut., Eur., al.): <g>οἶκος</g>, <r v=\"Matt.12.44\"></r>, <r v=\"Luke.11.25\"></r> (T [WH], R, om.).†</s>"},"G4956":{"l":"συστατικός","o":1,"ar":"<f>* <o>συ-στατικός</o>، <g>-ή, -όν</g> </f> <s n=\"1.\"><b>للضمّ والتركيب، بنّاء</b>. </s> <s n=\"2.\"><b>للتعريف والتقديم، للتوصية</b>: <g>ἐπιστολή</g> (رسالة توصية)، <r v=\"2Cor.3.1\"></r>.†</s>","en":"<f>* <o>συ-στατικός</o> (Tr. <g>συν-</g>), <g>-ή, -όν</g> </f> <et> <e t=\"derivation\">(&lt; <x><g>συνίστημι</g></x>), </e> </et> <s n=\"1.\"><b>for putting together, constructive</b>. </s> <s n=\"2.\"><b>for bringing together, introductory, commendatory</b>: <g>ἐπιστολή</g> (Arist., Diog. L., al.; and v. MM, xxiv), <r v=\"2Cor.3.1\"></r>.†</s>"},"G4995":{"l":"σωφρονισμός","o":1,"ar":"<f>*† <o>σωφρονισμός</o>، <g>-οῦ, ὁ</g></f> <s n=\"(a)\">عند الكتّاب المتأخرين: <b>تأديب، إنذار</b>؛ </s> <s n=\"(b)\"><b>ضبط النفس، نصح (تعقّل)</b>: <r v=\"2Tim.1.7\"></r>.†</s>","en":"<f>*† <o>σωφρονισμός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σωφρονίζω</g></x>), </e> </et> <s n=\"(a)\"><b>an admonishing</b> (FlJ, Plut., al.); </s> <s n=\"(b)\"><b>self-control, self-discipline</b>: <r v=\"2Tim.1.7\"></r> (on the reflexive meaning here, v. Ellic., in l.).†</s>"},"G4967":{"l":"σφαγή","o":3,"ar":"<f><o>σφαγή</o>، <g>-ῆς, ἡ</g></f> <s><b>ذبح</b>: <r v=\"Acts.8.32\"></r> <i>(السبعينية)</i>؛ <g>πρόβατα σφαγῆς</g>، <r v=\"Rom.8.36\"></r> <i>(السبعينية)</i>؛ <g>ἡμέρα σφαγῆς</g>، <r v=\"Jas.5.5\"></r>.†</s>","en":"<f><o>σφαγή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σφάζω</g></x>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H2873\">טֶבַח</h>, <h n=\"H2028\">הֲרֵגָה</h>, etc. ;]</e> </et> <s><b>slaughter</b>: <r v=\"Acts.8.32\"></r> <i>(LXX)</i>; <g>πρόβατα σφαγῆς</g>, <r v=\"Rom.8.36\"></r> <i>(LXX)</i>; <g>ἡμέρα σφαγῆς</g>, <r v=\"Jas.5.5\"></r>.†</s>"},"G4913":{"l":"συνήδομαι","o":1,"ar":"<f>* <o>συν-ήδομαι </o></f> <s><b>فرح معًا</b>؛ مع القابل: <b>فرح مع أو بـ، سُرّ بـ</b>: <g>τ. νόμῳ τ. θεοῦ</g>، <r v=\"Rom.7.22\"></r>.†</s>","en":"<f>* <o>συν-ήδομαι </o></f> <s><b>to rejoice together</b>; c. dat., <b>to rejoice with or in</b>: <g>τ. νόμῳ τ. θεοῦ</g>, <r v=\"Rom.7.22\"></r> (v. Lft., <i>Notes</i>, 304).†</s>"},"G4976":{"l":"σχῆμα","o":2,"ar":"<f><o>σχῆμα</o>، <g>-τος, τό</g></f> <s><b>هيئة، شكل</b>: <r v=\"1Cor.7.31\"></r>، <r v=\"Phil.2.8\"></r>.†</s>","en":"<f><o>σχῆμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἔχω</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Isa.3.17\"></r> (<h n=\"H6596\">פֹּת</h>) * ;]</e> </et> <s><b>figure, fashion</b>: <r v=\"1Cor.7.31\"></r>, <r v=\"Phil.2.8\"></r>.†</s> <sy><i>SYN.</i>: v.s. <x><g>μορφή</g></x> </sy>"},"G4909":{"l":"συνευδοκέω","o":6,"ar":"<f>** <o>συν-ευ-δοκέω</o>، <g>-ῶ</g></f> <s><b>يشترك في الاستحسان، يرضى، يوافق على</b> أو <b>مع</b>: مطلقًا، <r v=\"Acts.22.20\"></r>؛ مع القابل للشخص، <r v=\"Rom.1.32\"></r>؛ مع القابل للشيء، <r v=\"Luke.11.48\"></r>، <r v=\"Acts.8.1\"></r>؛ مع المصدر، <r v=\"1Cor.7.12-1Cor.7.13\"></r>.† </s>","en":"<f>** <o>συν-ευ-δοκέω</o>, <g>-ῶ</g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Macc.1.57\"></r>, <r v=\"1Macc.4.28\"></r> <h>א</h><i>1</i>, <r v=\"2Macc.11.24\"></r>, <r v=\"2Macc.11.35\"></r> * ;]</e> </et> <s><b>to join in approving, consent, agree to or with</b>: absol., <r v=\"Acts.22.20\"></r>; c. dat. pers., <r v=\"Rom.1.32\"></r>; c. dat. rei, <r v=\"Luke.11.48\"></r>, <r v=\"Acts.8.1\"></r>; c. inf., <r v=\"1Cor.7.12-1Cor.7.13\"></r> (chiefly in late writers).† </s>"},"G4931":{"l":"συντελέω","o":6,"ar":"<f><o>συν-τελέω</o>، <g>-ῶ </g></f> <s>صيغة «تامّة» من <g>τελέω</g>، </s> <s n=\"1.\"><b>يُكمل، يُتمّ، يُنهي</b>: <r v=\"Luke.4.13\"></r>؛ المبني للمجهول، <r v=\"Luke.4.2\"></r>، <r v=\"John.2.3\"></r>، <r v=\"Acts.21.27\"></r>. </s> <s n=\"2.\"><b>يُنجز، يحقّق، يُتمّم</b>: <r v=\"Mark.13.4\"></r>، <r v=\"Rom.9.28\"></r>، <r v=\"Heb.8.8\"></r>.†</s>","en":"<f><o>συν-τελέω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3615\">כּלה</h> pi., also for <h n=\"H6213\">עשׂה</h>, <h n=\"H8552\">תּמם</h>, etc. ;]</e> </et> <s>\"perfective\" of <g>τελέω</g> (cf. M, <i>Pr.</i>, 118), </s> <s n=\"1.\"><b>to complete, finish, bring to an end</b>: <r v=\"Luke.4.13\"></r>; pass., <r v=\"Luke.4.2\"></r>, <r v=\"John.2.3\"></r>, WH, mg., <r v=\"Acts.21.27\"></r>. </s> <s n=\"2.\"><b>to effect, accomplish, bring to fulfilment</b> (cf. MM, xxiv): <r v=\"Mark.13.4\"></r>, <r v=\"Rom.9.28\"></r>, <r v=\"Heb.8.8\"></r>.†</s>"},"G4998":{"l":"σώφρων","o":4,"ar":"<f>** <o>σώφρων</o>، <g>-ον </g></f> <s n=\"(a)\"><b>سليم العقل، عاقل، رشيد</b>؛ </s> <s n=\"(b)\"><b>ضابط نفسه، متعقّل، رزين</b>: <r v=\"1Tim.3.2\"></r>، <r v=\"Titus.1.8\"></r> <r v=\"Titus.2.2\"></r>، <r v=\"Titus.2.5\"></r>.†</s>","en":"<f>** <o>σώφρων</o>, <g>-ον </g></f> <et> <e t=\"septuagint\">[in LXX: IV Mac <i>9</i> * ;]</e> </et> <s n=\"(a)\"><b>of sound mind, sane, sensible</b>; </s> <s n=\"(b)\"><b>self-controlled, sober-minded</b>: <r v=\"1Tim.3.2\"></r>, <r v=\"Titus.1.8\"></r> <r v=\"Titus.2.2\"></r>, <r v=\"Titus.2.5\"></r> (Arist.).†</s>"},"G4938":{"l":"σύντριμμα","o":1,"ar":"<f><o>σύν-τριμμα</o>، <g>-τος, τό</g></f> <s><b>كسر، انكسار</b> (<r v=\"Lev.21.19\"></r>، وفي مواضع أخرى). مجازيًا: <b>بلية، خراب، سحق</b> (<r v=\"Isa.59.7\"></r>، <r v=\"Wis.3.3\"></r>، وفي مواضع أخرى): <r v=\"Rom.3.16\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>σύν-τριμμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>συντρίβω</g></x>), </e> <e t=\"septuagint\">[in LXX (<r v=\"Lev.21.19\"></r>, al.) chiefly for <h n=\"H7667\">שֶׁבֶר</h>; also for <h n=\"H7701\">שֹׁד</h> (<r v=\"Isa.59.7\"></r>), etc. ;] </e> </et> <s><b>a fracture</b> (Arist.; <r v=\"Lev.21.19\"></r>, al.). Metaph., <b>calamity, destruction</b> (<r v=\"Isa.59.7\"></r>, <r v=\"Wis.3.3\"></r>, al.): <r v=\"Rom.3.16\"></r> <i>(LXX)</i>.†</s>"},"G4944":{"l":"συνωδίνω","o":1,"ar":"<f>* <o>συν-ωδίνω </o></f> <s><b>تمخّض معًا</b>: مجازيًا، <r v=\"Rom.8.22\"></r>.†</s>","en":"<f>* <o>συν-ωδίνω </o></f> <s><b>to be in travail together</b> (Arist.): metaph. (Eur.), <r v=\"Rom.8.22\"></r>.†</s>"},"G4930":{"l":"συντέλεια","o":6,"ar":"<f><o>συντέλεια</o>، <g>-ας, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>دفع مشترك أو مساهمة</b> في خدمة عامة؛ ومن ثَمّ عمومًا <b>عمل مشترك</b>. </s> <s n=\"2.\">عند الكتّاب المتأخرين وفي العهد الجديد: <b>انقضاء، إتمام</b>: <g>σ. τ. αἰῶνος, -ων</g> (قارن <r v=\"Dan.12.13\"></r>، وفي مواضع أخرى)، <r v=\"Matt.13.39-Matt.13.40\"></r>، <r v=\"Matt.13.49\"></r> <r v=\"Matt.24.3\"></r> <r v=\"Matt.28.20\"></r>، <r v=\"Heb.9.26\"></r>.†</s>","en":"<f><o>συντέλεια</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>συντελέω</g></x>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3615\">כָּלָה</h> and (in Da) for <h n=\"H6965\">קֵץ</h> ;] </e> </et> <s n=\"1.\">in cl., <b>a joint payment or contribution</b> for public service; hence, generally, <b>joint action</b> (Plat.). </s> <s n=\"2.\">In late writers (Polyb., al.), <b>consummation, completion</b>: <g>σ. τ. αἰῶνος, -ων</g> (cf. <r v=\"Dan.12.13\"></r>, al.), <r v=\"Matt.13.39-Matt.13.40\"></r>, <r v=\"Matt.13.49\"></r> <r v=\"Matt.24.3\"></r> <r v=\"Matt.28.20\"></r>, <r v=\"Heb.9.26\"></r>.†</s>"},"G4969":{"l":"σφάζω","o":10,"ar":"<f><o>σφάζω </o></f> <s><b>ذبح، نحر</b> (خاصةً عن الذبائح المقدَّمة): <g>ἀρνίον</g>، <r v=\"Rev.5.6\"></r>، <r v=\"Rev.5.12\"></r> <r v=\"Rev.13.8\"></r>؛ عن الأشخاص، <r v=\"1John.3.12\"></r>، <r v=\"Rev.5.9\"></r> <r v=\"Rev.6.4\"></r>، <r v=\"Rev.6.9\"></r> <r v=\"Rev.18.24\"></r>؛ <g>ἐσφαγμένη εἰς θάνατον</g> (في الترجمة المنقحة: <b>مجروح حتى الموت</b>)، <r v=\"Rev.13.3\"></r> (قارن <g>κατα-σφάζω</g>).†</s>","en":"<f><o>σφάζω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7819\">שׁחט</h> ;] </e> </et> <s><b>to slay, slaughter</b> (esp. of victims for sacrifice): <g>ἀρνίον</g>, <r v=\"Rev.5.6\"></r>, <r v=\"Rev.5.12\"></r> <r v=\"Rev.13.8\"></r>; of persons, <r v=\"1John.3.12\"></r>, <r v=\"Rev.5.9\"></r> <r v=\"Rev.6.4\"></r>, <r v=\"Rev.6.9\"></r> <r v=\"Rev.18.24\"></r>; <g>ἐσφαγμένη εἰς θάνατον</g> (RV, <b>smitten unto death</b>), <r v=\"Rev.13.3\"></r> (cf. <g>κατα-σφάζω</g>).†</s>"},"G4936":{"l":"συντρέχω","o":3,"ar":"<f><o>συν-τρέχω </o></f> <s><b>ركض معًا أو مع</b>: يليه <g>ἐκεῖ</g>، <r v=\"Mark.6.33\"></r>؛ <g>πρόσ</g>، مع المنصوب، <r v=\"Acts.3.11\"></r>؛ مجازيًا، <r v=\"1Pet.4.4\"></r>.†</s>","en":"<f><o>συν-τρέχω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ps.50.18\"></r> (<h n=\"H5973\">עִם</h> <h n=\"H7521\">רָצָה</h>), II Mac <i>2</i>, Jdt <i>4</i> * ;] </e> </et> <s><b>to run together or with</b>: seq. <g>ἐκεῖ</g>, <r v=\"Mark.6.33\"></r>; <g>πρόσ</g>, c. acc., <r v=\"Acts.3.11\"></r>; metaph., <r v=\"1Pet.4.4\"></r>.†</s>"},"G4901":{"l":"συνεπιμαρτυρέω","o":1,"ar":"<f>* <o>συν-επι-μαρτυρέω</o></f> <s><b>شهد مع غيره، أيّد بشهادته</b>: <r v=\"Heb.2.4\"></r>.†</s>","en":"<f>* <o>συν-επι-μαρτυρέω</o>, <g>-ῶ </g></f> <s><b>to join in attesting, bear witness together with</b>: <r v=\"Heb.2.4\"></r> (Arist., Polyb., al.).†</s>"},"G4924":{"l":"συνοικέω","o":1,"ar":"<f><o>συν-οικέω</o>، <g>-ῶ </g></f> <s><b>سكن معًا، عاش مع</b>: عن الزوج وزوجته، مع القابل للشخص، <r v=\"1Pet.3.7\"></r>،†</s>","en":"<f><o>συν-οικέω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1167\">בּעל</h> etc. ;] </e> </et> <s><b>to dwell together</b>: of man and wife (Hdt., al.), c. dat. pers., <r v=\"1Pet.3.7\"></r>,†</s>"},"G4975":{"l":"σχέδον","o":3,"ar":"<f>** <o>σχέδον</o></f> ظرف <s n=\"1.\">للمكان، <b>قريبًا</b>. </s> <s n=\"2.\">للدرجة، <b>تقريبًا، نحو</b>: <r v=\"Acts.13.44\"></r> <r v=\"Acts.19.26\"></r>، <r v=\"Heb.9.22\"></r>.†</s>","en":"<f>** <o>σχέδον</o></f> adv. <et> <e t=\"derivation\">(&lt; <x><g>ἔχω</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.5.2\"></r>, <r v=\"3Macc.5.14\"></r>, <r v=\"3Macc.5.45\"></r> * ;] </e> </et> <s n=\"1.\">of place, <b>near</b>. </s> <s n=\"2.\">Of degree, <b>almost, nearly</b>: <r v=\"Acts.13.44\"></r> <r v=\"Acts.19.26\"></r>, <r v=\"Heb.9.22\"></r>.†</s>"},"G4970":{"l":"σφόδρα","o":11,"ar":"<f><o>σφόδρα </o> ظرف (أصلاً المحايد من <g>σφοδρός</g>، <i>مفرط، عنيف</i>) </f> <s><b>جدًّا، كثيرًا جدًّا، للغاية</b>: مع الأفعال، <r v=\"Matt.17.6\"></r>، <r v=\"Matt.17.23\"></r>، <r v=\"Matt.18.31\"></r>، <r v=\"Matt.19.25\"></r>، <r v=\"Matt.26.22\"></r>، <r v=\"Matt.27.54\"></r>، <r v=\"Acts.6.7\"></r>؛ مع الصفات، <r v=\"Matt.2.10\"></r>، <r v=\"Mark.16.4\"></r>، <r v=\"Luke.18.23\"></r>، <r v=\"Rev.16.21\"></r>.†</s>","en":"<f><o>σφόδρα </o> adv. (prop. neut. of <g>σφοδρός</g>, <i>excessive, violent</i>) </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3966\">מְאֹד</h> ;] </e> </et> <s><b>very, very much, exceedingly</b>: with verbs, <r v=\"Matt.17.6\"></r>, <r v=\"Matt.17.23\"></r> <r v=\"Matt.18.31\"></r> <r v=\"Matt.19.25\"></r> <r v=\"Matt.26.22\"></r> <r v=\"Matt.27.54\"></r>, <r v=\"Acts.6.7\"></r>; with adjectives, <r v=\"Matt.2.10\"></r>, <r v=\"Mark.16.4\"></r>, <r v=\"Luke.18.23\"></r>, <r v=\"Rev.16.21\"></r>.†</s>"},"G4951":{"l":"σύρω","o":5,"ar":"<f><o>σύρω </o></f> <s><b>جرّ، سحب</b>: مع منصوب الشيء، <r v=\"John.21.8\"></r>، <r v=\"Rev.12.4\"></r>؛ مع منصوب الشخص، عن الاقتياد إلى المحاكمة أو العقاب، <r v=\"Acts.8.3\"></r>؛ <g>ἔξω τ. πόλεως</g>، <r v=\"Acts.14.19\"></r>؛ <g>ἐπὶ τ. πολιτάρχας</g> (قارن <r v=\"4Macc.6.1\"></r>)، <r v=\"Acts.17.6\"></r> (قارن <g>κατα-σύρω</g>).†</s>","en":"<f><o>σύρω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Kgs.17.13\"></r> (<h n=\"H5498\">סחב</h>), <r v=\"4Macc.6.1\"></r>, al. ;] </e> </et> <s><b>to draw, drag</b>: c. acc. rei, <r v=\"John.21.8\"></r>, <r v=\"Rev.12.4\"></r>; c. acc. pers., of taking to trial or punish­ment, <r v=\"Acts.8.3\"></r>; <g>ἔξω τ. πόλεως</g>, <r v=\"Acts.14.19\"></r>; <g>ἐπὶ τ. πολιτάρχας</g> (cf. <r v=\"4Macc.6.1\"></r>), <r v=\"Acts.17.6\"></r> (cf. <g>κατα-σύρω</g>).†</s>"},"G4910":{"l":"συνευωχέω","o":2,"ar":"<f>* <o>συν-ευωχέω</o>، <g>-ῶ </g></f> <s><b>يُضيف (يولم) مع آخرين</b>. المبني للمجهول: <b>يتنعّم أو يأكل الولائم مع آخرين</b>: <r v=\"Jude.1.12\"></r>؛ مع القابل للشخص، <r v=\"2Pet.2.13\"></r>.†</s>","en":"<f>* <o>συν-ευωχέω</o>, <g>-ῶ </g></f> <s><b>to entertain together</b>. Pass., <b>to fare sumptuously or feast together or with</b>: <r v=\"Jude.1.12\"></r>; c. dat. pers., <r v=\"2Pet.2.13\"></r> (Arist., Luc., al.).†</s>"},"G4933":{"l":"συντηρέω","o":3,"ar":"<f><o>συν-τηρέω</o>، <g>-ῶ </g></f> <s>صيغة تأكيدية (perfective) من <g>τηρέω</g>، </s> <s n=\"1.\"><b>حفظ، صان، احتفظ به بعناية</b>: مع منصوب الشخص، <r v=\"Mark.6.20\"></r>؛ مع منصوب الشيء، <r v=\"Matt.9.17\"></r>؛ <g>ἐν τ. καρδίᾳ</g>، <r v=\"Luke.2.19\"></r>.†</s>","en":"<f><o>συν-τηρέω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ezek.18.19\"></r> (<h n=\"H8104\">שׁמר</h>), <r v=\"Dan.7.28\"></r> A (<h n=\"H5202\">נְטַר</h>), <r v=\"Sir.13.12\"></r> and freq., <r v=\"Tob.1.11\"></r>, <r v=\"2Macc.12.42\"></r>, al. ;] </e> </et> <s>\"perfective\" of <g>τηρέω</g> (v. M, <i>Pr.</i>, 113, 116), </s> <s n=\"1.\"><b>to preserve, keep safe, keep close</b>: c. acc. pers., <r v=\"Mark.6.20\"></r>; c. acc. rei, <r v=\"Matt.9.17\"></r>; <g>ἐν τ. καρδίᾳ</g>, <r v=\"Luke.2.19\"></r> (Arist. and later writers; cf. MM, xxiv).†</s>"},"G4977":{"l":"σχίζω","o":11,"ar":"<f><o>σχίζω </o></f> <s><b>شقَّ، مزَّق</b>: <r v=\"Matt.27.51\"></r>، <r v=\"Mark.1.10\"></r>، <r v=\"Mark.15.38\"></r>، <r v=\"Luke.5.36\"></r>، <r v=\"Luke.23.45\"></r>، <r v=\"John.19.24\"></r>، <r v=\"John.21.11\"></r>؛ مجازيًا، في المبني للمجهول، <b>انقسم</b> إلى أحزاب، <r v=\"Acts.14.4\"></r>، <r v=\"Acts.23.7\"></r>.† </s>","en":"<f><o>σχίζω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1234\">בּקע</h> ;] </e> </et> <s><b>to cleave, rend</b>: <r v=\"Matt.27.51\"></r>, <r v=\"Mark.1.10\"></r> <r v=\"Mark.15.38\"></r>, <r v=\"Luke.5.36\"></r> <r v=\"Luke.23.45\"></r>, <r v=\"John.19.24\"></r> <r v=\"John.21.11\"></r>; metaph., in pass., <b>to be divided</b> into factions, <r v=\"Acts.14.4\"></r> <r v=\"Acts.23.7\"></r>.† </s>"},"G4974":{"l":"σφυδρόν","o":1,"ar":"<f>*† <o>σφυδρόν</o>، <g>-οῦ, τό </g></f> <s>= <g>σφυρόν</g>، </s> <s><b>الكعب</b>: <r v=\"Acts.3.7\"></r>.†</s>","en":"<f>*† <o>σφυδρόν</o>, <g>-οῦ, τό </g></f> <s>= <g>σφυρόν</g>, </s> <s><b>the ankle</b>: <r v=\"Acts.3.7\"></r> (v. Bl., § 6, 8).†</s>"},"G4968":{"l":"σφάγιον","o":1,"ar":"<f><o>σφάγιον</o>، <g>-ου, τό</g></f> <s><b>ذبيحة</b> مُعدَّة للذبح: <r v=\"Acts.7.42\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>σφάγιον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>σφαγή</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Amos.5.25\"></r> (<h n=\"H2077\">זֶבַח</h>), <r v=\"Ezek.21.10\"></r>, <r v=\"Ezek.21.15\"></r>, <r v=\"Ezek.21.28\"></r> (<h n=\"H2874\">טֶבַח</h>), <r v=\"Lev.22.23\"></r> (<h n=\"H5071\">נְדָבָה</h>) * ;]</e> </et> <s><b>a victim</b> for slaughter: <r v=\"Acts.7.42\"></r> <i>(LXX)</i>.†</s>"},"G4950":{"l":"Σύρτις","o":1,"ar":"<f><o>Σύρτις</o>، <g>-εως</g>، حالة النصب <g>-ιν, ἡ</g>، </f> <s><b>السيرتس</b>، اسم لرصيفين رمليين كبيرين على الساحل الليبي: <r v=\"Acts.27.17\"></r>.†</s>","en":"<f><o>Σύρτις</o> (L, <g>σῦρτις</g>), <g>-εως</g>, acc. <g>-ιν, ἡ</g>, </f> <s><b>Syrtis</b>, the name of two large sand-banks on the Libyan coast: <r v=\"Acts.27.17\"></r>.†</s>"},"G4900":{"l":"συνελαύνω","o":null,"ar":"<f>** <o>συν-ελαύνω </o></f> <s><b>ساق معًا، أرغم على الاجتماع</b>: <g>εἰς εἰρήνην</g>، <r v=\"Acts.7.26\"></r>، في النص المستلَم (وفي غيره <g>συνήλλασσεν</g>).†</s>","en":"<f>** <o>συν-ελαύνω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.4.26\"></r>, <r v=\"2Macc.4.42\"></r> <r v=\"2Macc.5.5\"></r> * ;] </e> </et> <s><b>to drive together, force together</b>: <g>εἰς εἰρήνην</g>, <r v=\"Acts.7.26\"></r>, Rec. (WH, RV, <g>συνήλλασσεν</g>).†</s>"},"G4986":{"l":"Σώπατρος","o":1,"ar":"<f><o>Σώπατρος</o>، <g>-ου, ὁ </g></f> <s><b>سوباترس</b>: <r v=\"Acts.20.4\"></r>.†</s>","en":"<f><o>Σώπατρος</o>, <g>-ου, ὁ </g></f> <s><b>Sopater</b>: <r v=\"Acts.20.4\"></r>.†</s>"},"G4966":{"l":"Συχέμ","o":2,"ar":"<f><o>Συχέμ </o> لا يُصرَّف (العبرية <h n=\"H7926\">שְׁכֶם</h>)، </f> <s><b>شكيم</b>؛ </s> <s n=\"1.\">ابن حمور (<r v=\"Gen.33.19\"></r>): <r v=\"Acts.7.16\"></r>. </s> <s n=\"2.\">مدينة في السامرة (وفي السبعينية أحيانًا أيضًا <g>Σίκιμα, -ων</g>): <r v=\"Acts.7.16\"></r>.†</s>","en":"<f><o>Συχέμ </o> indecl. (Heb. <h n=\"H7926\">שְׁכֶם</h>), </f> <s><b>Shechem</b>; </s> <s n=\"1.\">the son of Hamor (<r v=\"Gen.33.19\"></r>): <r v=\"Acts.7.16\"></r>, Rec. </s> <s n=\"2.\">A city of Samaria (AV, Sychem; in LXX also sometimes <g>Σίκιμα, -ων</g>, as in FlJ): <r v=\"Acts.7.16\"></r>.†</s>"},"G4953":{"l":"σύσσημον","o":1,"ar":"<f>† <o>σύσ-σημον</o>، <g>-ου, τό</g> </f> <s><b>علامة أو إشارة متفق عليها</b>: <r v=\"Mark.14.44\"></r>. †</s>","en":"<f>† <o>σύσ-σημον</o> (T, <g>συν-</g>), <g>-ου, τό</g> </f> <et> <e t=\"derivation\">(&lt; <g>σῆμα</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Judg.20.38\"></r>, <r v=\"Judg.20.40\"></r> (<h n=\"H4864\">מַשְׂאֵת</h>), <r v=\"Isa.5.26\"></r> <r v=\"Isa.49.22\"></r> <r v=\"Isa.62.10\"></r> (<h n=\"H5251\">נֵס</h>) * ;] </e> </et> <s><b>a fixed sign or signal</b>: <r v=\"Mark.14.44\"></r>. (Strab., Plut., al.; condemned by Atticists, v. Rutherford, <i>NPhr.</i>, 492 f.) †</s>"},"G4979":{"l":"σχοινίον","o":2,"ar":"<f><o>σχοινίον</o>، <g>-ου, τό</g></f> <s><b>حبل</b> (أصلاً حبل مصنوع من الأَسَل): <r v=\"John.2.15\"></r>، <r v=\"Acts.27.32\"></r>.†</s>","en":"<f><o>σχοινίον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(dimin. of <g>σχοῖνος</g>, <i>a rush</i>), </e> </et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2256\">חֶבֶל</h>;]</e> <s><b>a rope</b> (prop., one made of rushes): <r v=\"John.2.15\"></r>, <r v=\"Acts.27.32\"></r>.†</s>"},"G4955":{"l":"στασιαστής","o":null,"ar":"<f>*† <o>στασιαστής</o></f> <s>= <g>στασιώτης</g> في الأتيكية، </s> <s><b>متمرِّد، ثائر، مثير للفتنة</b>: <r v=\"Mark.15.7\"></r>.†</s>","en":"<f>*† <o>στασιαστής</o></f> <et> <e t=\"derivation\">(&lt; <g>στασιάζω</g>, <b>to stir up sedition</b>, <r v=\"Jdt.7.15\"></r>, <r v=\"2Macc.4.30\"></r> <r v=\"2Macc.14.6\"></r> *)</e> </et> <s>= Att.. <g>στασιώτης</g>, </s> <s><b>a rebel, revolutionist, one who stirs up sedition</b>: <r v=\"Mark.15.7\"></r> (FlJ, al.).†</s>"},"G4952":{"l":"συσπαράσσω","o":2,"ar":"<f>*† <o>συ-σπαράσσω </o></f> <s><b>يصرع تمامًا</b> (يهزّ بتشنّج): مع المنصوب للشخص، <r v=\"Mark.9.20\"></r>، <r v=\"Luke.9.42\"></r> (قارن <g>σπαράσσω</g>).†</s>","en":"<f>*† <o>συ-σπαράσσω </o></f> <s><b>to convulse completely</b>: c. acc. pers., <r v=\"Mark.9.20\"></r>, <r v=\"Luke.9.42\"></r> (cf. <g>σπαράσσω</g>).†</s>"},"G4935":{"l":"συντόμως","o":2,"ar":"<f><o>συν-τόμως</o>، </f> ظرف <s>بإيجاز، باختصار: <r v=\"Acts.24.4\"></r>.†</s>","en":"<f><o>συν-τόμως</o>, </f> adv. <et> <e t=\"derivation\">(&lt; <x><g>συντέμνω</g></x>) </e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.13.23\"></r> (<h n=\"H3808\">בְּלֹא</h><h n=\"H4941\">מׅשְׁפָּט</h>) <r v=\"Prov.23.28\"></r>, <r v=\"3Macc.5.25\"></r> * ;] </e> </et> <s>concisely, briefly: <r v=\"Acts.24.4\"></r> (for a similar ex., v. MM, xxiv).†</s>"},"G4922":{"l":"συνοδεύω","o":1,"ar":"<f>† <o>συν-οδεύω </o></f> <s><b>يسافر مع</b>: مع القابل للشخص، <r v=\"Acts.9.7\"></r>.†</s>","en":"<f>† <o>συν-οδεύω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Zech.8.21\"></r> <h>א</h><i>1</i> (<h n=\"H1980\">הלך</h>), <r v=\"Tob.5.16\"></r><h>א</h>, <r v=\"Wis.6.23\"></r> * ;] </e> </et> <s><b>to journey with</b>: c. dat. pers., <r v=\"Acts.9.7\"></r> (Plut., al.).†</s>"},"G4927":{"l":"συνομορέω","o":1,"ar":"<f>*† <o>συν-ομορέω</o>، <g>-ῶ </g></f> <s><b>يتاخم، يكون ملاصقًا لـ</b>: مع القابل، <r v=\"Acts.18.7\"></r>.†</s>","en":"<f>*† <o>συν-ομορέω</o>, <g>-ῶ </g></f> <s><b>to border on</b>: c. dat., <r v=\"Acts.18.7\"></r> (Byz.).†</s>"},"G4946":{"l":"Συράκουσαι","o":1,"ar":"<f><o>Συράκουσαι</o>، <g>-ῶν, αἱ </g></f> <s><b>سراكوسا</b>: <r v=\"Acts.28.12\"></r>.†</s>","en":"<f><o>Συράκουσαι</o>, <g>-ῶν, αἱ </g></f> <s><b>Syracuse</b>: <r v=\"Acts.28.12\"></r>.†</s>"},"G4965":{"l":"Συχάρ","o":1,"ar":"<f><o>Συχάρ</o></f> <s><b>سوخار</b>، بلدة في السامرة: <r v=\"John.4.5\"></r>.†</s>","en":"<f><o>Συχάρ</o></f> <et> <e t=\"derivation\">(<g>Ε, Σιχάρ</g>), indecl., <g>ἡ</g>,</e> </et> <s><b>Sychar</b>, a town of Samaria: <r v=\"John.4.5\"></r>.†</s>"},"G4926":{"l":"συνομιλέω","o":1,"ar":"<f>* <o>συν-ομιλέω</o>، <g>-ῶ </g></f> <s><b>تحادث مع</b>: مع القابل للشخص، <r v=\"Acts.10.27\"></r>.†</s>","en":"<f>* <o>συν-ομιλέω</o>, <g>-ῶ </g></f> <s><b>to converse with</b> (absol., FlJ, <i>BJ</i>, v, 13, 1; seq. <g>μετά</g>, Cebes, 13): c. dat. pers., <r v=\"Acts.10.27\"></r>.†</s>"},"G4999":{"l":"ταβέρνη","o":null,"ar":"<f>*† <o>ταβέρνη</o></f> <s>(باللاتينية <l>taberna</l>)، انظر تحت مدخل <g>Τρεῖς Ταβέρναι.</g> </s>","en":"<f>*† <o>ταβέρνη</o></f> <s>(Lat. <l>taberna</l>), v.s. <g>Τρεῖς Ταβέρναι.</g> </s>"},"G4981":{"l":"σχολή","o":1,"ar":"<f><o>σχολή</o>، <g>-ῆς, ἡ </g></f> <s n=\"1.\"><b>فراغ</b>. </s> <s n=\"2.\">لاحقًا: </s> <s n=\"(a)\">ما يُشغَل به الفراغ، <b>مناظرة، محاضرة</b>؛ </s> <s n=\"(b)\">المكان الذي تُلقى فيه المحاضرات، <b>مدرسة</b>: <r v=\"Acts.19.9\"></r>.†</s>","en":"<f><o>σχολή</o>, <g>-ῆς, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Gen.33.14\"></r> (<g>κατὰ σ.</g>, <h n=\"H328\">לְאִטִּי</h>), <r v=\"Prov.28.19\"></r>, <r v=\"Sir.38.24\"></r> * ;] </e> </et> <s n=\"1.\"><b>leisure</b>. </s> <s n=\"2.\">Later (from Plato on), </s> <s n=\"(a)\">that for which leisure is employed, <b>a disputation, lecture</b>; </s> <s n=\"(b)\">the place where lectures are delivered, <b>a school</b>: <r v=\"Acts.19.9\"></r> (for the later sense of <b>employment</b>, v. MM, xxiv).†</s>"},"G4963":{"l":"συστροφή","o":2,"ar":"<f><o>συ-στροφή</o>، <g>-ῆς, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>التفاف، التواء معًا</b>. </s> <s n=\"2.\"><b>تجمهر، تجمّع شغب</b>: <r v=\"Acts.19.40\"></r>؛ <g>σ. ποιεῖσθαι</g> (<r v=\"Amos.7.10\"></r>)، <b>عقد اتفاقًا</b> (<b>تحالفوا معًا</b>): <r v=\"Acts.23.12\"></r>.†</s>","en":"<f><o>συ-στροφή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>συστρέφω</g></x>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Hos.4.19\"></r> <r v=\"Hos.13.12\"></r> (<h n=\"H6887\">צרר</h>); <g>σ. ποιεῖσθαι</g>, <r v=\"Amos.7.10\"></r> (<h n=\"H7194\">קשׁר</h>), etc. ;] </e> </et> <s n=\"1.\"><b>a twisting together</b> (Plat.). </s> <s n=\"2.\"><b>a concourse, a riotous gathering</b> (Polyb.): <r v=\"Acts.19.40\"></r>; <g>σ. ποιεῖσθαι</g> (<r v=\"Amos.7.10\"></r>), <b>to make a compact</b> (RV, <b>banded themselves together</b>): <r v=\"Acts.23.12\"></r>.†</s>"},"G4948":{"l":"Σύρος","o":1,"ar":"<f><o>Σύρος</o>، <g>-ου, ὁ</g>، المؤنث <g>Σύρα</g>،</f> <s><b>سرياني، أرامي</b>: <r v=\"Luke.4.27\"></r>، <r v=\"Mark.7.26\"></r>.† </s>","en":"<f><o>Σύρος</o>, <g>-ου, ὁ</g>, fem. <g>Σύρα</g>,</f> <s><b>a Syrian</b>: <r v=\"Luke.4.27\"></r>, <r v=\"Mark.7.26\"></r>, WH, mg.† </s>"},"G4940":{"l":"συντυγχάνω","o":1,"ar":"<f>** <o>συν-τυγχάνω </o></f> <s><b>التقى بـ، وصل إلى</b>: مع القابل للشخص، <r v=\"Luke.8.19\"></r>.†</s>","en":"<f>** <o>συν-τυγχάνω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.8.14\"></r> * ;] </e> </et> <s><b>to meet with, fall in with</b>: c. dat. pers., <r v=\"Luke.8.19\"></r>.†</s>"},"G4939":{"l":"σύντροφος","o":1,"ar":"<f><o>σύν-τροφος</o>، <g>-ου, ὁ</g></f> <s n=\"1.\">أصلاً، <b>من تغذّى أو تربّى مع آخر، أخ بالتربية</b>: <r v=\"Acts.13.1\"></r> (بحسب الترجمات الإنجليزية). </s> <s n=\"2.\">في الاستعمال الهلّيني، لقبًا في البلاط، <b>صديق حميم</b> للملك: <r v=\"Acts.13.1\"></r>.†</s>","en":"<f><o>σύν-τροφος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>συντρέφομαι</g>, <i>to be brought up together</i>) </e> <e t=\"septuagint\">[in LXX: <r v=\"1Kgs.12.24\"></r>, <r v=\"1Macc.1.6\"></r> R, <r v=\"2Macc.9.29\"></r> * ;]</e> </et> <s n=\"1.\">prop., <b>one nourished or brought up with, a foster-brother</b>: <r v=\"Acts.13.1\"></r> EV. </s> <s n=\"2.\">In Hellenistic usage, as a court term, <b>an intimate friend</b> of a king (v. Deiss., <i>BS</i>, 305, 310 f.): <r v=\"Acts.13.1\"></r> (cf. also MM, xxiv).†</s>"},"G4962":{"l":"συστρέφω","o":2,"ar":"<f><o>συ-στρέφω </o></f> <s n=\"1.\"><b>لفّ معًا، جمع</b>: مع منصوب الشيء، <r v=\"Acts.28.3\"></r>. </s> <s n=\"2.\">المبني للمجهول، عن الأشخاص، <b>تجمّعوا معًا</b>: <r v=\"Matt.17.22\"></r>.†</s>","en":"<f><o>συ-στρέφω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7194\">קשׁר</h> ;] </e> </et> <s n=\"1.\"><b>to twist together</b>: c. acc. rei, <r v=\"Acts.28.3\"></r>. </s> <s n=\"2.\">Pass., of persons, <b>to gather themselves together</b>: <r v=\"Matt.17.22\"></r> (WH, R, mg.).†</s>"},"G4929":{"l":"συντάσσω","o":3,"ar":"<f><o>συν-τάσσω </o></f> <s><b>أمر، رسم، رتّب</b>: مع القابل للشخص، <r v=\"Matt.21.6\"></r> <r v=\"Matt.26.19\"></r> <r v=\"Matt.27.10\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>συν-τάσσω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6680\">צוה</h> pi. ;] </e> </et> <s><b>to prescribe, ordain, arrange</b>: c. dat. pers, <r v=\"Matt.21.6\"></r> <r v=\"Matt.26.19\"></r> <r v=\"Matt.27.10\"></r> <i>(LXX)</i>.†</s>"},"G4917":{"l":"συνθλάω","o":2,"ar":"<f><o>συν-θλάω</o>، <g>-ῶ </g></f> <s><b>سحق، رضّض</b>: <r v=\"Matt.21.44\"></r>، <r v=\"Luke.20.18\"></r>.†</s>","en":"<f><o>συν-θλάω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H4272\">מחץ</h> etc. ;] </e> </et> <s><b>to crush together, crush</b>: <r v=\"Matt.21.44\"></r> ([WH], R, mg., om.), <r v=\"Luke.20.18\"></r>.†</s>"},"G4923":{"l":"συνοδία","o":1,"ar":"<f><o>συνοδία</o>، <g>-ας, ἡ </g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>سفر في رفقة</b>. </s> <s n=\"2.\">كناية، <b>جماعة من المسافرين، قافلة، رفقة</b>: <r v=\"Luke.2.44\"></r>.†</s>","en":"<f><o>συνοδία</o>, <g>-ας, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Neh.7.5\"></r>, <r v=\"Neh.7.64\"></r> (<h n=\"H3187\">יחשׂ</h>) * ;] </e> </et> <s n=\"1.\"><b>a journey in company</b> (Plut., al.). </s> <s n=\"2.\">By meton., <b>a company of travellers, a caravan</b>: <r v=\"Luke.2.44\"></r>.†</s>"},"G4911":{"l":"συνεφίστημι","o":1,"ar":"<f>* <o>συν-εφ-ίστημι </o></f> <s><b>أقام فوق</b>. المبني للمجهول، </s> <s n=\"1.\">في اليونانية الكلاسيكية: <b>وقف فوق</b>. </s> <s n=\"2.\"><b>قام معًا</b>: يليه <g>κατά</g> مع المضاف إليه للشخص (<b>ضدّ</b>)، <r v=\"Acts.16.22\"></r>.†</s>","en":"<f>* <o>συν-εφ-ίστημι </o></f> <s><b>to place over</b>. Pass., </s> <s n=\"1.\"><b>to stand over</b> (Thuc.). </s> <s n=\"2.\"><b>to rise together</b>: seq. <g>κατά</g>, c. gen. pers. (<b>against</b>), <r v=\"Acts.16.22\"></r>.†</s>"},"G4945":{"l":"συνωμοσία","o":1,"ar":"<f>** <o>συνωμοσία</o>، <g>-ας, ή</g></f> <s><b>مؤامرة</b>: <r v=\"Acts.23.13\"></r>.†</s>","en":"<f>** <o>συνωμοσία</o>, <g>-ας, ή</g></f> <et> <e t=\"derivation\">(<g>συνόμνυμι</g>, <i>to conspire</i>), </e> <e t=\"septuagint\">[in Sm.: <r v=\"Ezek.22.25\"></r> * ;] </e> </et> <s><b>a conspiracy</b>: <r v=\"Acts.23.13\"></r>.†</s>"},"G4949":{"l":"Συροφοινίκισσα","o":null,"ar":"<f><o>Συροφοινίκισσα</o>، <g>-ης, ἡ</g> </f> <s><b>امرأة فينيقية سورية</b>: <r v=\"Mark.7.26\"></r> (قارن <g>ἡ Φοινίκη Συρία</g>).†</s>","en":"<f><o>Συροφοινίκισσα</o> (Rec. <g>-φοίνισσα</g>), <g>-ης, ἡ</g> </f> <s><b>a Syropænician woman</b>: <r v=\"Mark.7.26\"></r>, WH, txt., RV (cf. <g>ἡ Φοινίκη Συρία</g>, Diod., 19, 93).†</s>"},"G4918":{"l":"συνθλίβω","o":2,"ar":"<f><o>συν-θλίβω </o></f> <s><b>ضغط، زحم من كل جانب</b>: <r v=\"Mark.5.24\"></r>، <r v=\"Mark.5.31\"></r>.†</s>","en":"<f><o>συν-θλίβω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Eccl.12.6\"></r> <h>א</h> A (<h n=\"H7533\">רצץ</h>), <r v=\"Sir.31.14\"></r>, <r v=\"1Macc.15.14\"></r> A * ;]</e> </et> <s><b>to press together, press on all sides</b>: <r v=\"Mark.5.24\"></r>, <r v=\"Mark.5.31\"></r>.†</s>"},"G4919":{"l":"συνθρύπτω","o":1,"ar":"<f>*† <o>συν-θρύπτω </o></f> <s><b>كسّر قطعًا، سحق</b>: مجازيًا، <g>τ. καρδίαν</g>، <r v=\"Acts.21.13\"></r>.†</s>","en":"<f>*† <o>συν-θρύπτω </o></f> <s><b>to break in pieces, crush</b>: metaph., <g>τ. καρδίαν</g>, <r v=\"Acts.21.13\"></r>.†</s>"},"G4934":{"l":"συντίθημι","o":3,"ar":"<f><o>συν-τίθημι </o></f> <s><b>وضع معًا، ضمّ</b>، بمعانٍ متنوعة. الصيغة الوسطى: </s> <s n=\"(a)\"><b>لاحظ، أدرك</b>؛ </s> <s n=\"(b)\"><b>عزم، اتفق، تعاهد</b>: مع المصدر، <r v=\"Luke.22.5\"></r>؛ يليه <g>τοῦ</g> مع المصدر، <r v=\"Acts.23.20\"></r>؛ يليه <g>ἵνα</g>، <r v=\"John.9.22\"></r>.†</s>","en":"<f><o>συν-τίθημι </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Sam.22.13\"></r> (<h n=\"H7194\">קשׁר</h>), etc. ;]</e> </et> <s><b>to place or put together</b>, in various senses. Mid., </s> <s n=\"(a)\"><b>to observe, perceive</b>; </s> <s n=\"(b)\"><b>to determine, agree, covenant</b>: c. inf., <r v=\"Luke.22.5\"></r>; seq. <g>τοῦ</g>, c. inf., <r v=\"Acts.23.20\"></r>; seq. <g>ἵνα</g>, <r v=\"John.9.22\"></r>.†</s>"},"G4902":{"l":"συνέπομαι","o":1,"ar":"<f>** <o>συν-έπομαι </o></f> <s><b>تبع مع، رافق</b>: مع قابل الشخص، <r v=\"Acts.20.4\"></r>.†</s>","en":"<f>** <o>συν-έπομαι </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.15.2\"></r>, <r v=\"3Macc.5.48\"></r> R <r v=\"3Macc.6.21\"></r> * ;]</e> </et> <s><b>to follow with, accompany</b>: c. dat. pers., <r v=\"Acts.20.4\"></r>.†</s>"}});A.got[49]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});